(window.FREALLY_I18N = window.FREALLY_I18N || {})["hi"] = {"hero.headline":"<span class=\"hl-muted\">आपका लूप। उनका अरेंजमेंट।</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">आपका ट्रैक।</span>","hero.cycle":"आपका ट्रैक।|आपके स्टेम्स।|आपका MIDI।","hero.sub":"किसी भी कलाकार, प्रोड्यूसर या शैली के अंदाज़ में 8-बार के लूप को एक तैयार, अरेंज किए हुए ट्रैक में बदलें — आपके DAW में लाइव बजाया गया, फिर ऑडियो स्टेम्स या MIDI सॉन्ग टेम्पलेट के रूप में ड्रैग करके बाहर निकाला गया। मुफ़्त, ऑफ़लाइन और 100% AI-मुक्त।","hero.chipStandalone":"स्टैंडअलोन","hero.chipWeb":"वेब ऐप","what.title":"यह क्या है","what.p1":"जो लूप बार 8 पर पूरा लगता है, वह बार 64 पर भी बस एक लूप ही होता है। उसे ट्रैक में बदलने का मतलब है घंटों म्यूट करना, कॉपी करना, काटना और ऑटोमेट करना — इंट्रो, हुक, ड्रॉप-आउट, स्विच-अप — और इसके बाद ही आप सुन पाते हैं कि आइडिया में दम है या नहीं।","what.p2":"Freally Unloop यह अरेंजमेंट आपके लिए करता है। इसे उस ट्रैक पर लगाएँ जो आपका लूप बजाता है, कोई कलाकार, प्रोड्यूसर या शैली चुनें, और प्ले दबाएँ: Unloop आपके अपने ऑडियो पर पूरा ट्रैक बजाता है, आपके प्रोजेक्ट के साथ ताल में, ठीक उसी तरह जैसे वह नाम अरेंज करता है।","what.p3":"फिर ट्रैक आपका है। इसे क्लिप-दर-क्लिप संपादित करें, जो पसंद हो उसे रखें और बाकी को फिर से बनाएँ, और इसे प्रिंट करें — मिक्स या हर पार्ट की एक फ़ाइल — ताकि सीधे अपने ट्रैकों पर ड्रैग कर सकें।","how.title":"यह कैसे काम करता है","how.loop.title":"लूप चलाएँ।","how.loop.body":"आपके 8 बार DAW में लूप होते हैं — या स्टेम्स या कोई MIDI लूप स्टैंडअलोन या वेब ऐप में डालें।","how.name.title":"एक नाम चुनें।","how.name.body":"2,413 कलाकारों, प्रोड्यूसरों और शैलियों में खोजें और एक मोड चुनें: हर शैली को कई तरह से अरेंज किया जा सकता है।","how.play.title":"प्ले दबाएँ।","how.play.body":"Unloop आपके अपने ऑडियो पर पूरा ट्रैक बजाता है — इंट्रो, हुक, ड्रॉप-आउट, 808 कट, स्टटर बिल्ड, टेप स्टॉप, बीट स्विच — आपके प्रोजेक्ट के साथ बिल्कुल ताल में।","how.shape.title":"इसे गढ़ें।","how.shape.body":"क्लिप को खिसकाएँ, कॉपी करें, विभाजित करें और फ़ेड करें, फ़ेडर चलाएँ, ऑटोमेशन बनाएँ, जो पसंद हो उसे लॉक करें और बाकी को फिर से बनाएँ।","how.take.title":"ले जाएँ।","how.take.body":"अरेंज किया हुआ ट्रैक WAV, AIFF, FLAC या MP3 के रूप में — मिक्स या स्टेम्स — या मल्टी-ट्रैक MIDI सॉन्ग टेम्पलेट के रूप में ड्रैग करके बाहर निकालें।","docs.language.title":"भाषाएँ","docs.language.p1":"Unloop अठारह भाषाएँ बोलता है। यह आपके सिस्टम की भाषा में शुरू होता है; दूसरी भाषा चुनने के लिए गियर बटन से “सेटिंग्स” खोलें और कोई एक चुनें।","ladder.title":"1.0 की ओर रास्ता","ladder.intro":"हर संस्करण के लिए एक पंक्ति। यह वही सीढ़ी है जिसका निजी योजना भी पालन करती है — अगर एक हिलती है, तो दूसरी भी हिलती है, और एक बिल्ड गेट दोनों की तुलना करता है।","ladder.rung.v0.1.0":"प्लगइन (CLAP, VST3, AU) और स्टैंडअलोन लोड होते हैं और ऑडियो गुज़ारते हैं; एडिटर का ढाँचा, डिज़ाइन टोकन, 18 भाषाएँ, हर क्वालिटी गेट, Windows और Linux पर लोकल CI, प्लगइन वैलिडेटर, ब्राउज़र टेस्ट।","ladder.rung.v0.2.0":"2,413 कलाकारों, प्रोड्यूसरों और शैलियों में से कोई भी एक नियतात्मक अरेंजमेंट प्लान बन जाता है, हर शैली के लिए कई मोड के साथ।","ladder.rung.v0.3.0":"लूप होती बीट पर एक इंस्टेंस पूरा ट्रैक लाइव बजाता है — बिना क्लिक के, ज़ीरो लेटेंसी, आपके DAW के साथ सिंक में।","ladder.rung.v0.4.0":"हर पार्ट के लिए एक इंस्टेंस, एक ही ट्रैक की तरह संचालित, पूरे कंसोल के साथ।","ladder.rung.v0.5.0":"कैप्चर, Unloop के अंदर प्रीव्यू, WAV/AIFF/FLAC/MP3 में प्रिंट, ड्रैग करके बाहर निकालना, लूप प्रोजेक्ट, और लूप लाइब्रेरी — अपने लूप ब्राउज़ करें, सुनकर परखें और काटें, हाल के प्रोजेक्ट फिर से खोलें — पहला संपूर्ण प्रोडक्ट: MVP।","ladder.rung.v0.6.0":"क्लिप को खिसकाना, कॉपी करना, विभाजित करना और उनका आकार बदलना; फ़ेड, फ़ेडर और ऑटोमेशन; लॉक करना और फिर से बनाना; असीमित पूर्ववत और फिर से करना; अरेंजमेंट शेल्फ़ और .unarr फ़ाइलें; हर संपादन कीबोर्ड से।","ladder.rung.v0.6.5":"इंटरफ़ेस ध्वनियाँ जो ठीक उतनी ही देर चलती हैं जितनी उनके पैनल, स्टैंडअलोन ऐप में बिना शीर्षक वाली गहरी टाइटल बार, और ऐप की अपनी त्रुटियों के लिए «रिपोर्ट» — हर Freally ऐप में एक जैसी।","ladder.rung.v0.6.7":"Blender में रेंडर किए गए नॉब, फ़ेडर, मीटर, कुंजियाँ, स्लाइडर और स्विच, दो थीम में — Freally हरे रंग पर हल्की और गहरी — Freally Flipcopy से कॉपी किए गए, हर Freally ऐप में एक जैसे।","ladder.rung.v0.7.0":"बिना AI के ऑडियो-से-MIDI, MIDI लूप इनपुट, MIDI सॉन्ग टेम्पलेट, वेलॉसिटी डॉक्टर, ऑडियो/MIDI टॉगल और MIDI ड्रैग-आउट।","ladder.rung.v0.8.0":"स्टैंडअलोन और वेब ऐप में स्टेम्स मोड, टेम्पो का पालन, लूप डॉक्टर।","ladder.rung.v0.9.0":"री-ड्रीम, सिंथेसाइज़ किए गए ट्रांज़िशन FX, बीट स्विच, अरेंजमेंट डॉक्टर, टेम्पलेट, MIDI लर्न।","ladder.rung.v0.10.0":"हर शैली कई मोड में, सैकड़ों प्रमुख कलाकार और प्रोड्यूसर, हर नाम ईमानदारी से पहचाना जाता है।","ladder.rung.v1.0.0b":"फ़ीचर-पूर्ण: एज केस, सुलभता, 18 भाषाएँ, परफ़ॉर्मेंस बजट, तीन सिस्टम के लिए इंस्टॉलर।","ladder.rung.v1.0.0-rc":"ऊपर से नीचे तक समीक्षा और हर बग ठीक, फिर हर उपलब्ध सिस्टम पर असली DAW में हाथ से जाँच — पूरा वेब ऐप और यह साइट तैयार होने के साथ।","ladder.rung.v1.0.0":"डाउनलोड खुलते हैं, और वेब ऐप लाइव हो जाता है।","ladder.rung.v1.1.0":"विविधता की गहराई।","ladder.rung.v1.2.0":"मूव्स की गहराई।","ladder.rung.v1.3.0":"वोकल को ध्यान में रखकर अरेंजिंग।","ladder.rung.v1.4.0":"परफ़ॉर्मेंस और DJ।","ladder.rung.v1.5.0":"Freally MIDI Master ब्रिज।","ladder.rung.v1.6.0":"रोस्टर और डेटासेट की गहराई।","ladder.rung.v1.7.0":"एक्सपोर्ट और इंटरऑपरेबिलिटी।","ladder.rung.v1.8.0":"वर्कफ़्लो और सुलभता की गहराई।","ladder.rung.v1.9.0":"Freally एकीकरण।","ladder.note":"जो संस्करण पूरा हो चुका है वह बना और टैग किया गया है। यह डाउनलोड नहीं है: अभी कोई नहीं है, और 1.0.0 तक कोई नहीं होगा।","honest.title":"वे बातें जिन्हें ज़्यादातर साइटें सबसे नीचे रखती हैं","honest.notes.title":"यह आपका संगीत अरेंज करता है; ख़ुद कोई संगीत नहीं लिखता","honest.notes.body":"अरेंज किए गए ट्रैक की हर आवाज़ आपके लूप से आती है, या फिर वह एक ट्रांज़िशन इफ़ेक्ट है जिसे Unloop ऑसिलेटर और नॉइज़ से बनाता है। यह तय करता है कि हर पार्ट कब बजे और उस पर मूव्स करता है, लेकिन यह नए संगीत का एक भी नोट नहीं लिखता और आपकी डिस्क पर रखी लूप फ़ाइल को कभी नहीं बदलता। कोई नया फ़िल, या स्विच के लिए दूसरी बीट, आपकी तरफ़ से आती है।","honest.bands.title":"एक स्टीरियो लूप तीन बैंड्स में अरेंज होता है","honest.bands.body":"जब काम करने के लिए सिर्फ़ एक तैयार स्टीरियो लूप हो, तो Unloop उसके लो, मिड और हाई बैंड्स पर मूव्स करता है, इसलिए कोई मूव स्नेयर को मेलोडी से अलग नहीं कर सकता। पूरे मूव्स के लिए हर पार्ट के अपने ट्रैक पर एक इंस्टेंस लगाएँ।","honest.styles.title":"नाम स्टाइल का वर्णन करते हैं","honest.styles.body":"कलाकार, प्रोड्यूसर और शैली के नाम केवल संगीत स्टाइल का वर्णन करने के लिए इस्तेमाल किए जाते हैं। Freally Unloop किसी भी कलाकार, प्रोड्यूसर, लेबल या अधिकार-धारक से संबद्ध नहीं है, न ही उनके द्वारा समर्थित, प्रायोजित या स्वीकृत है, और यह कभी किसी खास गाने का अरेंजमेंट दोबारा नहीं बनाता।","honest.styles.link":"पूरा अस्वीकरण पढ़ें (अंग्रेज़ी में)","honest.hands.title":"अभी हर DAW में हाथ से आज़माया नहीं गया","honest.hands.body":"Unloop Windows, Linux और macOS पर स्वचालित गेट्स द्वारा बनाया और जाँचा जाता है। असली DAW में, हर सिस्टम पर इसे हाथ से पूरी तरह परखना रिलीज़ कैंडिडेट का काम है, 1.0.0 से पहले।","honest.downloads.title":"1.0.0 से पहले कोई डाउनलोड नहीं है","honest.downloads.body":"इस पेज पर न कोई बीटा, न कोई प्रीव्यू बिल्ड, न अर्ली ऐक्सेस। आधा-अधूरा काम करने वाला अरेंजर उस अरेंजर से बुरा है जो अभी मौजूद ही नहीं।","honest.network.title":"यह कभी ऑनलाइन नहीं जाता","honest.network.body":"प्लगइन और स्टैंडअलोन ऐप में बिल्कुल भी नेटवर्किंग कोड नहीं है, और अगर कभी जोड़ा भी जाए तो एक बिल्ड गेट फेल हो जाता है। किसी आगामी संस्करण में एक अपडेट-चेक जोड़ा जा सकता है, जो तब तक बंद रहेगा जब तक आप उसे चालू न करें, और जिसे एक अलग प्रोग्राम चलाएगा।","site.tagline":"हर लूप एक ट्रैक है, जो बनने का इंतज़ार कर रहा है।","footer.licence":"स्वामित्व वाला — सर्वाधिकार सुरक्षित। © Mike Weaver. आज उपयोग के लिए मुफ़्त; भविष्य के संस्करण बेचे जा सकते हैं। ओपन सोर्स नहीं।","footer.yours":"Unloop से बनाया गया संगीत आपका है — उस हद तक, जिस हद तक आपके अरेंज किए गए लूप इस्तेमाल करने का अधिकार आपके पास था — बिना किसी रॉयल्टी और बिना किसी श्रेय की ज़रूरत के।","featuresPage.lead":"Freally Unloop 8-बार के लूप को 2,413 कलाकारों, प्रोड्यूसरों और शैलियों में से किसी के भी अंदाज़ में एक तैयार, अरेंज किए हुए ट्रैक में बदल देता है — आपके अपने साउंड पर, आपके DAW में लाइव बजाया गया, फिर ऑडियो स्टेम्स या MIDI सॉन्ग टेम्पलेट के रूप में ड्रैग करके बाहर निकाला गया।","featuresPage.version":"यह पेज Freally Unloop के संस्करण 1.0 का वर्णन करता है: इस पर लिखी हर चीज़ 1.0 में है, और 1.0 के बाद के लिए नियोजित कुछ भी इस पर नहीं है।","featuresPage.numbers.names":"कलाकार, प्रोड्यूसर और शैलियाँ, जिनके अंदाज़ में अरेंज करें","featuresPage.numbers.artists":"कलाकार","featuresPage.numbers.producers":"प्रोड्यूसर","featuresPage.numbers.genres":"शैलियाँ","featuresPage.numbers.flagships":"प्रमुख स्टाइल, उनके खास मूव्स तक","featuresPage.numbers.lanes":"ऑटोमेशन लेन, हर पार्ट पर","featuresPage.numbers.formats":"एक्सपोर्ट फ़ाइल फ़ॉर्मैट: WAV, AIFF, FLAC, MP3 और MIDI","featuresPage.numbers.latency":"सैंपल अतिरिक्त लेटेंसी","featuresPage.numbers.systems":"ऑपरेटिंग सिस्टम: Windows, macOS और Linux","featuresPage.numbers.languages":"भाषाएँ","featuresPage.numbers.ai":"AI मॉडल","featuresPage.numbers.price":"आज की क़ीमत","featuresPage.free.title":"आज मुफ़्त","featuresPage.free.body":"Unloop आज जो कुछ भी करता है, वह सबके लिए मुफ़्त है: कोई पेड टियर नहीं, कोई सब्सक्रिप्शन नहीं, कोई खाता नहीं, कोई लाइसेंस की नहीं, कोई विज्ञापन नहीं और कोई ट्रायल नहीं जो ख़त्म हो जाए। इससे बनाए गए अरेंजमेंट, ऑडियो, स्टेम्स और MIDI आपके हैं — उस हद तक, जिस हद तक आपके अरेंज किए गए लूप इस्तेमाल करने का अधिकार आपके पास था।","featuresPage.cards.title":"संस्करण 1.0 क्या करता है","featuresPage.cards.search.title":"शैली नहीं, नाम खोजें","featuresPage.cards.search.body":"एक ही खोज में 2,413 कलाकार, प्रोड्यूसर और शैलियाँ — उपनामों और टाइपो के बावजूद। कुछ भी दबाने से पहले एक कार्ड बताता है कि वह नाम क्या करता है: उसके गानों का ढाँचा, अरेंज करने के उसके तरीके, उसके सेक्शन की लंबाई और उसके खास मूव्स।","featuresPage.cards.modes.title":"हर शैली का बस एक टेम्पलेट नहीं","featuresPage.cards.modes.body":"एक शैली कई तरह से अरेंज होती है — रेडियो कट, मिक्सटेप कट, क्लब कट, स्विच-अप, न्यूनतम — जब तक कि उसका सच में एक ही तरीका न हो, और तब उसका कार्ड बताता है कि क्यों। कलाकार और प्रोड्यूसर अपने तरीके जोड़ते हैं, और हर बार दबाने पर एक नया सीड मिलता है, जिसे आप सँभालकर रख सकते हैं और पेस्ट करके वही अरेंजमेंट वापस पा सकते हैं।","featuresPage.cards.live.title":"पूरा ट्रैक, लाइव बजाया गया","featuresPage.cards.live.body":"प्ले दबाएँ और Unloop आपके अपने ऑडियो पर ट्रैक बजाता है, आपके प्रोजेक्ट के साथ ताल में: इंट्रो, हुक, ड्रॉप-आउट, 808 कट, फ़िल्टर स्वीप, स्टटर बिल्ड, टेप स्टॉप, हाफ़-टाइम और बीट स्विच। किसी मूव में क्लिक नहीं होता, और कोई भी मूव लेटेंसी नहीं जोड़ता।","featuresPage.cards.pattern.title":"उस लूप पर भी जो कभी आगे नहीं बढ़ता","featuresPage.cards.pattern.body":"FL Studio का पैटर्न मोड और Ableton का सेशन व्यू सॉन्ग पोज़िशन आगे बढ़ाए बिना लूप करते हैं। Unloop लूप ख़ुद गिनता है, इसलिए बार-बार घूमते 8 बार पर भी पूरा ट्रैक बजता है।","featuresPage.cards.parts.title":"एक लूप, या हर पार्ट","featuresPage.cards.parts.body":"एक स्टीरियो लूप काफ़ी है: Unloop उसे लो, मिड और हाई बैंड्स में अरेंज करता है। या फिर हर पार्ट के ट्रैक पर एक इंस्टेंस लगाएँ, और उनमें से एक बाकी सबको एक ही ट्रैक की तरह संचालित करता है, फ़ेडरों और लैंपों वाले पूरे कंसोल के साथ।","featuresPage.cards.timeline.title":"टाइमलाइन आपकी है","featuresPage.cards.timeline.body":"हर क्लिप को खिसकाएँ, कॉपी करें, विभाजित करें, उसका आकार बदलें और तीन हैंडल वाले फ़ेड से फ़ेड करें; क्लिप, पार्ट और मास्टर फ़ेडर चलाएँ; हर पार्ट पर 12 लेन में ऑटोमेशन बनाएँ; सेक्शन का क्रम बदलें; जो पसंद हो उसे लॉक करें और बाकी को फिर से बनाएँ। असीमित पूर्ववत, और एक ऑटोसेव जो क्रैश के बाद भी सुरक्षित रहता है।","featuresPage.cards.take.title":"पहले सुनें, फिर ले जाएँ","featuresPage.cards.take.body":"जब आपका DAW रुका हो, तब Unloop के अंदर ही अरेंजमेंट का प्रीव्यू सुनें। इसे WAV, AIFF, FLAC या MP3 में प्रिंट करें — मिक्स, या हर पार्ट का एक स्टेम — और पूरा गाना, एक पार्ट या एक सेक्शन सीधे अपने ट्रैकों पर ड्रैग करें। हर फ़ाइल के साथ एक रसीद जाती है।","featuresPage.cards.midi.title":"ऑडियो या MIDI, बस एक स्विच","featuresPage.cards.midi.body":"MIDI पर स्विच करें और वही अरेंजमेंट एक मल्टी-ट्रैक MIDI सॉन्ग टेम्पलेट बन जाता है, जो आपके अपने लूप के नोट्स से पढ़ा जाता है, सेक्शन मार्करों के साथ। वेलॉसिटी डॉक्टर हर पार्ट को सही तरह की वेलोसिटी देता है: ड्रम पर एक्सेंट और घोस्ट नोट्स, एकसार 808, बराबर कॉर्ड्स।","featuresPage.cards.shelf.title":"एक लूप, कई अरेंजमेंट","featuresPage.cards.shelf.body":"हर लूप एक बार, अपने अलग प्रोजेक्ट के रूप में सेव होता है, नाम वाले अरेंजमेंट की एक शेल्फ़ के साथ: अगले बार पर उनके बीच बदलें, किन्हीं दो की तुलना करें, और किसी एक को फ़ाइल के रूप में दूसरे लूप पर ले जाएँ। लूप लाइब्रेरी में आपके सारे लूप रहते हैं, सुनकर परखने के लिए तैयार।","featuresPage.cards.standalone.title":"एक स्टैंडअलोन ऐप और एक वेब ऐप","featuresPage.cards.standalone.body":"आठ तक स्टेम्स या MIDI फ़ाइलें डालें और बिना DAW के उन्हें अरेंज करें। जब साथ चलने के लिए कोई DAW न हो, तो Unloop कलाकार का टेम्पो सुझाता है और आपके लूप को उस टेम्पो पर स्ट्रेच कर सकता है; लूप डॉक्टर जोड़ पर क्लिक, क्लिपिंग और मेल न खाने वाला टेम्पो ढूँढ़ता है।","featuresPage.cards.redream.title":"री-ड्रीम और अरेंजमेंट डॉक्टर","featuresPage.cards.redream.body":"री-ड्रीम आपके मौजूदा अरेंजमेंट के तीन नए रूप देता है, उसका ढाँचा बनाए रखते हुए। सिंथेसाइज़ किए गए राइज़र और इम्पैक्ट, अपना प्रोड्यूसर टैग और बीट स्विच जोड़ें, फिर अरेंजमेंट डॉक्टर को देर से आने वाला हुक या कभी न बदलने वाला सेक्शन दिखाने दें — सुधार के साथ।","featuresPage.cards.offline.title":"ऑफ़लाइन, निजी, कोई AI नहीं","featuresPage.cards.offline.body":"न कोई खाता, न टेलीमेट्री, न कोई मॉडल: एक नियम-आधारित प्लानर और पारंपरिक सिग्नल प्रोसेसिंग, जिसे एक बिल्ड गेट जाँचता है। प्लगइन और स्टैंडअलोन कभी ऑनलाइन नहीं जाते; एकमात्र अपवाद एक अपडेट जाँच है, जो तब तक बंद रहती है जब तक आप उसे चालू न करें, और जिसे एक अलग प्रोग्राम चलाता है।","featuresPage.compare.title":"व्यावसायिक टूल्स के साथ आमने-सामने","featuresPage.compare.intro":"Freally Unloop 1.0 की तुलना आज बिकने वाले पाँच प्रोडक्ट्स से, जो किसी लूप को अरेंज करते हैं, उसके वेरिएशन बनाते हैं या पूरे गाने लिखते हैं: ArrangerKing (एक अरेंजमेंट प्लगइन), Loopmix (एक लूप-रीमिक्स प्लगइन), Songen (बीट बनाने वाला ऐप), और Suno व SOUNDRAW (AI सॉन्ग जनरेटर)। किसी दूसरे प्रोडक्ट का हर खाना उसके निर्माता के अपने पेजों से लिया गया है, जिन्हें 1 और 2 अक्टूबर 2026 को जाँचा गया, और क़ीमतें टैक्स से पहले अमेरिकी डॉलर में हैं, जैसी 2 अक्टूबर 2026 को सूचीबद्ध थीं।","featuresPage.compare.feature":"फ़ीचर","featuresPage.compare.row.price":"क़ीमत (USD, अक्टूबर 2026)","featuresPage.compare.freeToday":"आज मुफ़्त","featuresPage.compare.price.songen":"मुफ़्त टियर; Premium $89.99 प्रति वर्ष","featuresPage.compare.price.suno":"मुफ़्त टियर; Pro $10 और Premier $30 प्रति माह","featuresPage.compare.price.soundraw":"$16.99 प्रति माह से; स्टेम्स $35.99 से","featuresPage.compare.row.yourLoop":"आपके अपने लूप को आपके लिए पूरे गाने में बदलता है, कोई नया संगीत लिखे बिना","featuresPage.compare.legend.yes":"उपलब्ध","featuresPage.compare.legend.partly":"आंशिक","featuresPage.compare.note.setMutes":"हर म्यूट आप ख़ुद सेट करते हैं","featuresPage.compare.note.variations":"लूप के वेरिएशन","featuresPage.compare.legend.no":"उपलब्ध नहीं","featuresPage.compare.note.writesOwn":"अपना संगीत ख़ुद लिखता है","featuresPage.compare.note.writesNew":"नया संगीत लिखता है","featuresPage.compare.row.styleOf":"आपके बताए कलाकार या प्रोड्यूसर के अंदाज़ में अरेंज करता है","featuresPage.compare.note.names":"2,340 नाम","featuresPage.compare.note.genreTemplates":"शैली के टेम्पलेट","featuresPage.compare.note.genres":"शैलियाँ","featuresPage.compare.note.nameStops":"नाम लिखने पर गाना रुक सकता है","featuresPage.compare.note.genresMoods":"शैलियाँ और मूड","featuresPage.compare.row.moves":"आपके अपने ऑडियो पर बजाए गए मूव्स: 808 कट, स्टटर बिल्ड, टेप स्टॉप","featuresPage.compare.note.mutesOnly":"सिर्फ़ म्यूट","featuresPage.compare.note.gateReverse":"गेट, रिवर्स, पिच","featuresPage.compare.row.edit":"हर क्लिप, फ़ेड, फ़ेडर और ऑटोमेशन लेन संपादन योग्य","featuresPage.compare.note.partsMutes":"पार्ट और म्यूट","featuresPage.compare.note.arrangementNotes":"अरेंजमेंट और नोट्स","featuresPage.compare.note.premierStudio":"Premier, Studio में","featuresPage.compare.note.muteSolo":"म्यूट, सोलो, तीव्रता","featuresPage.compare.row.stems":"ऑडियो स्टेम्स एक्सपोर्ट","featuresPage.compare.note.ofLoop":"एक लूप के","featuresPage.compare.note.paidPlans":"पेड प्लान में","featuresPage.compare.note.artistPro":"Artist Pro और उससे ऊपर","featuresPage.compare.row.midi":"MIDI फ़ाइल के रूप में गाना","featuresPage.compare.note.fromYourLoop":"आपके अपने लूप से","featuresPage.compare.note.guideTracks":"सिर्फ़ गाइड ट्रैक","featuresPage.compare.row.plugin":"आपके DAW में एक प्लगइन","featuresPage.compare.row.systems":"Windows, macOS और Linux पर नेटिव","featuresPage.compare.note.wine":"Linux पर सिर्फ़ Wine के ज़रिए","featuresPage.compare.note.browser":"ब्राउज़र में","featuresPage.compare.row.offline":"ऑफ़लाइन काम करता है","featuresPage.compare.legend.unknown":"सत्यापित नहीं","featuresPage.compare.row.account":"न खाता, न टेलीमेट्री","featuresPage.compare.note.usageData":"उपयोग डेटा भेजता है","featuresPage.compare.note.account":"खाता ज़रूरी","featuresPage.compare.row.noAi":"कहीं भी AI नहीं","featuresPage.compare.note.buildGate":"बिल्ड गेट से जाँचा गया","featuresPage.compare.note.ownAi":"इसका अपना AI","featuresPage.compare.summaryTitle":"संक्षेप में","featuresPage.compare.summary":"संक्षेप में: सिर्फ़ Unloop ही आपके अपने लूप को, आपके बताए कलाकार या प्रोड्यूसर के अंदाज़ में, आपके लिए एक पूरे ट्रैक में बदलता है, और मूव्स आपके अपने ऑडियो पर बजाए जाते हैं। Windows और macOS के साथ-साथ Linux पर भी नेटिव चलने वाला यही अकेला है, और यही अकेला है जो बिना खाते, बिना टेलीमेट्री और बिना AI के ऑफ़लाइन काम करता है।","featuresPage.compare.theyWinTitle":"वे कहाँ आगे हैं","featuresPage.compare.theyWin":"वे कहाँ आगे हैं: Suno, SOUNDRAW और Songen आपके लिए नया संगीत लिखते हैं — जो Unloop जान-बूझकर कभी नहीं करता। Loopmix किसी लूप को गाने में अरेंज करने के बजाय उसके अंदर के हिस्सों को काटकर नए क्रम में लगाता है, और यह Pro Tools के लिए एक AAX प्लगइन भी है, जो Unloop 1.0 नहीं है।","featuresPage.compare.asOf":"Unloop का कॉलम संस्करण 1.0 का है, जो अभी आया नहीं है, और उसकी क़ीमत आज की है: Unloop आज मुफ़्त है, और भविष्य के संस्करण बेचे जा सकते हैं। बाकी प्रोडक्ट भी बदलते रहते हैं; यह तालिका 2 अक्टूबर 2026 की स्थिति के अनुसार है। प्रोडक्ट के नाम उनके मालिकों के ट्रेडमार्क हैं, और Freally Unloop इनमें से किसी से संबद्ध नहीं है।","featuresPage.why.title":"यह इस तरह क्यों बना है","featuresPage.why.sound.title":"आपका साउंड, अरेंज किया हुआ — कभी बदला नहीं जाता","featuresPage.why.sound.body":"अरेंज किए गए ट्रैक की हर आवाज़ आपके लूप से आती है, या फिर वह एक ट्रांज़िशन इफ़ेक्ट है जिसे Unloop ऑसिलेटर और नॉइज़ से बनाता है। यह आपके गाने में नए संगीत का एक भी नोट नहीं लिखता, और आपकी डिस्क पर रखी लूप फ़ाइल को कभी नहीं बदलता।","featuresPage.why.rules.title":"नियम, जिन्हें आप पढ़ सकते हैं","featuresPage.why.rules.body":"एक प्लानर हर कलाकार, प्रोड्यूसर और शैली के लिए शोध किया हुआ अरेंजमेंट डेटा पढ़ता है, और कोई आवाज़ बजने से पहले ही हर सेक्शन और मूव तय कर लेता है। वही लूप, नाम, मोड और सीड आज भी और पाँच साल बाद भी वही अरेंजमेंट देते हैं — इसलिए जो सीड आप किसी साथी को भेजते हैं, वह उन्हें ठीक वही सुनाता है जो आपने सुना।","featuresPage.why.views.title":"दो नज़रिए, एक सच","featuresPage.why.views.body":"ऑडियो और MIDI सॉन्ग टेम्पलेट एक ही प्लान से बनते हैं, और हर संपादन दोनों तक पहुँचता है। जब MIDI यह नहीं बता सकता कि किसी मूव ने क्या किया — जैसे टेप स्टॉप में पिच का नीचे गिरना — तो उस मूव को चुपचाप हटाने के बजाय सिर्फ़-ऑडियो के रूप में चिह्नित किया जाता है।","featuresPage.why.local.title":"सब कुछ आपकी मशीन पर रहता है","featuresPage.why.local.body":"न खाता, न टेलीमेट्री, न क्लाउड। आपके लूप और आपके ट्रैक कभी आपके कंप्यूटर से बाहर नहीं जाते, और अगर नेटवर्क कोड प्लगइन या स्टैंडअलोन तक पहुँचे तो एक बिल्ड गेट फ़ेल हो जाता है। वेब ऐप एक बार लोड होता है, फिर ऑफ़लाइन काम करता है और कुछ भी अपलोड नहीं करता।","featuresPage.why.tempo.title":"यह आपके DAW के साथ चलता है","featuresPage.why.tempo.body":"प्लगइन हमेशा आपके प्रोजेक्ट के टेम्पो पर बजता है और उसे कभी नहीं बदलता। जब आपके चुने कलाकार या प्रोड्यूसर किसी दूसरे टेम्पो पर काम करते हैं, तो Unloop वह टेम्पो सुझाता है, और हाफ़-टाइम व डबल-टाइम को भी मेल मानता है। स्टैंडअलोन और वेब ऐप में यह आपके लूप को उनके टेम्पो पर स्ट्रेच कर सकता है।","featuresPage.why.styles.title":"स्टाइल, गाने कभी नहीं","featuresPage.why.styles.body":"एक नाम सिर्फ़ यह बताता है कि कोई कैसे अरेंज करता है, इससे ज़्यादा कुछ नहीं। Unloop कभी किसी खास गाने का अरेंजमेंट दोबारा नहीं बनाता, और जब तक आप ख़ुद न डालें, आपकी फ़ाइलों के नामों में कोई नाम नहीं डालता।","featuresPage.coming.title":"अभी क्या आना बाकी है","featuresPage.coming.intro":"साफ़-साफ़ बताया गया है, क्योंकि जो फ़ीचर सूची अपनी कमियाँ छिपाए, वह पढ़ने लायक नहीं। यह पेज संस्करण 1.0 का वर्णन करता है, और Unloop एक-एक पायदान करके बन रहा है, इसलिए इस पर लिखा सब कुछ अभी बना नहीं है। 1.0 की ओर रास्ते के हर पायदान पर उसकी स्थिति लिखी है।","featuresPage.limits.title":"1.0 क्या नहीं करता","featuresPage.limits.newMusic":"यह नया संगीत नहीं लिखता। कोई नया फ़िल, या बीट स्विच के लिए दूसरा पैटर्न, आपकी तरफ़ से आता है: Unloop वही अरेंज करता है जो आपके लूप में है, और सिर्फ़ अपने सिंथेसाइज़ किए ट्रांज़िशन इफ़ेक्ट जोड़ता है।","featuresPage.limits.songs":"यह किसी मशहूर गाने का अरेंजमेंट दोबारा नहीं बनाता, और कभी नहीं बनाएगा।","featuresPage.limits.bands":"एक स्टीरियो लूप तीन बैंड्स में अरेंज होता है, इसलिए कोई मूव स्नेयर को मेलोडी से अलग नहीं कर सकता। पूरे मूव्स के लिए हर पार्ट को उसका अपना ट्रैक दें; प्रिंट करते समय पर्कसिव और हार्मोनिक हिस्सों में बँटवारा मदद करता है, और Unloop बताता है कि यह एक अनुमान है।","featuresPage.limits.midi":"ऑडियो से बना इसका MIDI साफ़ बताता है कि यह क्या नहीं कर सकता: ऑडियो से कोई काउंटर-मेलोडी नहीं, कॉर्ड्स सीधे-सादे रूप में लिखे जाते हैं, और गाई गई लाइन अंदाज़े से भरने के बजाय छोड़ दी जाती है।","featuresPage.limits.daw":"यह एक अरेंजर है, DAW नहीं: न रिकॉर्डिंग, न प्लगइन होस्टिंग, और अपने पार्ट और मास्टर फ़ेडरों के अलावा कोई मिक्सर नहीं।","featuresPage.limits.aax":"यह Pro Tools (AAX) प्लगइन नहीं है।","featuresPage.coming.downloads":"संस्करण 1.0 से पहले कोई डाउनलोड नहीं है, और इस पेज पर भी कोई नहीं।","docs.intro":"यह मैनुअल संस्करण 0.7.0 का वर्णन करता है, जो आज बना हुआ संस्करण है। फ़ीचर्स पेज की कोई चीज़ जहाँ किसी बाद के संस्करण में आती है, वहाँ मैनुअल बताता है कि किस संस्करण में।","docs.start.title":"शुरुआत करना","docs.agreement.title":"लाइसेंस अनुबंध","docs.window.title":"विंडो","docs.name.title":"नाम चुनना","docs.generate.title":"जनरेट, मोड और सीड","docs.tempo.title":"टेम्पो और घड़ी","docs.parts.title":"एक लूप, या हर पार्ट","docs.capture.title":"कैप्चर और प्रीव्यू","docs.print.title":"प्रिंट, ड्रैग और रसीदें","docs.projects.title":"लूप प्रोजेक्ट और लूप लाइब्रेरी","docs.timeline.title":"टाइमलाइन संपादित करना","docs.fades.title":"फ़ेड और फ़ेडर","docs.automation.title":"ऑटोमेशन","docs.sections.title":"सेक्शन","docs.reroll.title":"लॉक, फिर से बनाना और हाथ से मूव्स","docs.history.title":"पूर्ववत, फिर से करें और ऑटोसेव","docs.shelf.title":"एक लूप पर कई अरेंजमेंट","docs.midi.title":"MIDI व्यू और वेलॉसिटी डॉक्टर","docs.keys.title":"कीबोर्ड शॉर्टकट","docs.sounds.title":"इंटरफ़ेस ध्वनियाँ और टाइटल बार","docs.look.title":"थीम, कंट्रोल और मोशन","docs.privacy.title":"निजता और नेटवर्क","docs.report.title":"किसी समस्या की रिपोर्ट करना","docs.limits.title":"ज्ञात सीमाएँ","docs.start.p1":"Freally Unloop आपके DAW के अंदर CLAP या VST3 प्लगइन के रूप में, या macOS पर AU के रूप में चलता है, और अपने-आप में एक स्टैंडअलोन ऐप के रूप में भी। इसे उस ट्रैक पर लगाएँ जो आपका लूप बजाता है: जब तक आप “जनरेट करें” नहीं दबाते, यह ट्रैक का ऑडियो ठीक वैसा ही आगे जाने देता है जैसा वह आता है, इसलिए इसे वहीं लगा रहने देना सुरक्षित है।","docs.start.p2":"संस्करण 0.6.0 DAW में, ऑडियो के साथ इस्तेमाल के लिए बना है। MIDI संस्करण 0.7.0 में आता है; स्टैंडअलोन ऐप में डाले गए स्टेम्स को अरेंज करना, और वेब ऐप, संस्करण 0.8.0 में आते हैं।","docs.start.p3":"संस्करण 1.0.0 से पहले कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","docs.agreement.p1":"पहली बार खुलने पर Unloop अपना अंतिम उपयोगकर्ता लाइसेंस अनुबंध दिखाता है, जो अंग्रेज़ी में लिखा गया है। इसे अंत तक पढ़ें, तब “सहमत हूँ” बटन उपलब्ध हो जाता है।","docs.agreement.p2":"अगर आप अस्वीकार करते हैं, तो Unloop रुका रहता है: कुछ भी अरेंज नहीं होता, और आपका ऑडियो अब भी बिना बदलाव के गुज़रता है। जब भी आप तैयार हों, “दोबारा पढ़ें” चुनें। आपका जवाब आपके कंप्यूटर पर रखा जाता है, उस पर मौजूद Unloop की हर कॉपी के लिए।","docs.window.p1":"सबसे ऊपर लूप प्रोजेक्ट मेनू (फ़ोल्डर बटन), अरेंजमेंट मेनू, खोज, मोड, और “पूर्ववत करें” व “फिर से करें” हैं; दाईं ओर टेम्पो, घड़ी और “सेटिंग्स” (गियर)। बीच में अरेंजमेंट मैप है: ट्रैक के सेक्शन, हर पार्ट के लिए एक लेन, और उसके मूव्स। सबसे नीचे कंसोल है: “जनरेट करें”, हर पार्ट के लिए एक स्ट्रिप, मास्टर सेक्शन और सीड।","docs.window.p2":"सेटिंग्स में भाषा, थीम — सिस्टम, डार्क या लाइट —, इंटरफ़ेस ध्वनियाँ और कीबोर्ड शॉर्टकट की सूची है।","docs.name.p1":"2,413 कलाकारों, प्रोड्यूसरों और शैलियों में से किसी को भी ढूँढ़ने के लिए खोज में टाइप करें। उपनाम और मिलती-जुलती वर्तनी भी उन्हें ढूँढ़ लेती हैं, और Ø, ß और Ł जैसे अक्षर सामान्य अक्षरों से मेल खाते हैं, इसलिए “mo” लिखने पर MØ मिल जाता है। खोज ख़ाली होने पर यह आपके हाल के नाम और प्रमुख मॉडल दिखाती है। तीर कुंजियाँ और Enter इस्तेमाल करें, या क्लिक करें।","docs.name.p2":"हर नाम का एक मॉडल कार्ड होता है: वह किन मोड में अरेंज करता है और हर मोड कितनी बार चुना जाता है, उसके गानों का आम ढाँचा, उसके खास मूव्स, वह किन पार्ट को चलाता है, उसका डेटा कहाँ से आता है और वह कितना भरोसेमंद है। जिस नाम का अपना डेटा कम हो, वह अपनी शैली से विरासत में लेता है, और कार्ड यह पूरी कड़ी दिखाता है।","docs.generate.p1":"“जनरेट करें” दबाएँ और Unloop आपके चुने नाम के लिए पूरे ट्रैक की योजना बनाता है: हर सेक्शन, उसमें कौन-से पार्ट बजते हैं, और हर मूव। पहले एक मोड चुनें — रेडियो कट, मिक्सटेप कट, क्लब / DJ कट, स्विच-अप, न्यूनतम और अन्य, नाम के अनुसार — या इसे “कोई भी मोड” पर छोड़ दें और Unloop ख़ुद एक चुन लेता है।","docs.generate.p2":"हर प्लान का एक सीड होता है — कंसोल में 16 हेक्साडेसिमल अंक — और “जनरेट करें” हर बार दबाने पर एक नया सीड निकलता है। वही लूप, नाम, मोड और सीड हमेशा वही अरेंजमेंट देते हैं: किसी अरेंजमेंट को सँभालकर रखने या किसी साथी को भेजने के लिए सीड कॉपी करें, और उसे वापस पाने के लिए सीड पेस्ट करें।","docs.tempo.p1":"DAW में Unloop हमेशा आपके प्रोजेक्ट के टेम्पो पर बजता है और उसे कभी नहीं बदलता। टेम्पो चिप बताती है कि आपका टेम्पो उस सीमा में है या नहीं जिसमें वह नाम आम तौर पर काम करता है — हाफ़-टाइम और डबल-टाइम को भी मेल मानते हुए — और अगर नहीं है, तो अपने DAW को किस टेम्पो पर सेट करना है, उसे कॉपी करने के बटन के साथ।","docs.tempo.p2":"Unloop को यह जानना ज़रूरी है कि आपका लूप कितना लंबा है: यह पूछता है, और जब तक आप न बताएँ, 8 बार मानकर चलता है। घड़ी आपके DAW की सॉन्ग पोज़िशन का पालन करती है, या पोज़िशन आगे न बढ़े तो लूप ख़ुद गिनती है — FL Studio का पैटर्न मोड, या Ableton Live का सेशन व्यू — इसलिए बार-बार घूमते लूप पर भी पूरा ट्रैक बजता है। “स्वतः” आपके लिए तय करता है; ख़ुद तय करने के लिए “गीत” या “लूप” चुनें।","docs.parts.p1":"एक ही ट्रैक पर तैयार स्टीरियो लूप हो, तो Unloop उसे तीन बैंड्स में अरेंज करता है — लो, मिड और हाई — और मैप यह बताता है।","docs.parts.p2":"पूरे मूव्स के लिए हर पार्ट के ट्रैक पर एक इंस्टेंस लगाएँ और हर एक को एक भूमिका दें: ड्रम, बेस, मेलोडी, कॉर्ड्स वगैरह। Unloop ट्रैक के नाम से एक भूमिका सुझाता है। एक ही चैनल के इंस्टेंस मिलकर एक ही ट्रैक बजाते हैं: पहला इंस्टेंस संचालन करता है, और बाकी हर इंस्टेंस सैंपल तक सटीक उसके प्लान का पालन करता है और सिर्फ़ अपने पार्ट के मूव्स बजाता है। कंसोल हर इंस्टेंस के लिए एक स्ट्रिप दिखाता है, उसके फ़ेडर और लैंपों के साथ।","docs.parts.p3":"जब आपका DAW प्लगइन अलग-अलग प्रोसेस में चलाता है, तो इंस्टेंस आपके कंप्यूटर पर एक साझा फ़ाइल के ज़रिए मिलते हैं, नेटवर्क के ज़रिए कभी नहीं। अगर किसी चैनल पर पहले से किसी दूसरे प्रोजेक्ट का प्लान है, तो Unloop यह बताता है और दूसरा चैनल सुझाता है।","docs.capture.p1":"“जनरेट करें” के बाद हर इंस्टेंस अपने लूप का एक चक्र कैप्चर करता है — वह संगीत जो उसके ट्रैक पर आ रहा है, कभी उसका अपना आउटपुट नहीं — और उसके बाद से अरेंज किया हुआ ट्रैक मेमोरी से बजाता है। “लाइव / कैप्चर किया” चिप बताती है कि स्थिति क्या है, साथ में “फिर से कैप्चर करें” और “कैप्चर भूल जाएँ”। 64 सेकंड से लंबा लूप कैप्चर नहीं किया जा सकता, और कैप्चर के दौरान रुकना, किसी और जगह कूदना या टेम्पो बदलना उसे अगली बार चलाने पर फिर से शुरू कर देता है।","docs.capture.p2":"अगर आ रहा लूप अब वह नहीं है जो कैप्चर हुआ था, तो चिप पूछती है: लूप बदल गया — फिर से कैप्चर करें? बजते समय कुछ भी बदला नहीं जाता; फिर से कैप्चर तभी होता है जब आप दबाते हैं।","docs.capture.p3":"जब आपका DAW रुका हो, तब मास्टर सेक्शन के प्ले, पॉज़, स्टॉप और लूप बटन — या स्पेस बार — Unloop के अंदर ही पूरे ट्रैक का प्रीव्यू चलाते हैं, चैनल के सभी इंस्टेंस एक साथ। किसी जगह पर जाने के लिए मैप के रूलर पर क्लिक करें, या किसी सेक्शन को लूप करें। अपने DAW में प्ले दबाएँ और वह तुरंत कमान सँभाल लेता है।","docs.print.p1":"मास्टर सेक्शन का “प्रिंट” बटन “प्रिंट और एक्सपोर्ट” खोलता है। चुनें कि क्या प्रिंट करना है — मिक्स, स्टेम्स, कोई भी पार्ट, एक सेक्शन या पूरा ट्रैक — और फ़ॉर्मैट: WAV (16-बिट, 24-बिट या 32-बिट फ़्लोट), AIFF, FLAC या MP3, कैप्चर हुई सैंपल रेट पर या आपकी चुनी हुई रेट पर। यह उसी कोड से रेंडर होता है जो लाइव बजाता है, इसलिए फ़ाइल में वही होता है जो आपने सुना। “रद्द करें” कुछ भी पीछे नहीं छोड़ता।","docs.print.p2":"बिट डेप्थ घटने पर आप डिदर कर सकते हैं, मिक्स पर −1 dBTP का सेफ़्टी लिमिटर लगा सकते हैं, और रसीदें लिख सकते हैं। फ़ाइल नाम एक टेम्पलेट से बनते हैं जिसे आप संपादित कर सकते हैं, और डिफ़ॉल्ट रूप से किसी फ़ाइल नाम में किसी कलाकार या प्रोड्यूसर का नाम नहीं होता। एक्सपोर्ट पूरा होने पर प्रिंट मीटर मिक्स का पीक, ट्रू पीक और लाउडनेस दिखाता है।","docs.print.p3":"डायलॉग छोड़ना हो तो ड्रैग रैक इस्तेमाल करें: मिक्स, स्टेम्स, एक पार्ट या एक सेक्शन सीधे अपने ट्रैकों पर ड्रैग करें। ड्रैग शुरू होने से पहले फ़ाइलें रेंडर हो जाती हैं, डिफ़ॉल्ट रूप से 24-बिट WAV के रूप में।","docs.print.p4":"हर एक्सपोर्ट और हर ड्रैग के साथ एक रसीद जाती है — एक छोटी .unloop-receipt.json फ़ाइल। इसमें संस्करण, नाम, मोड और सीड होते हैं, और वे फ़िंगरप्रिंट भी जो वही ट्रैक दोबारा बनाने के लिए ज़रूरी हैं। रसीदें डिफ़ॉल्ट रूप से चालू रहती हैं; आप उन्हें डायलॉग में बंद कर सकते हैं।","docs.projects.p1":"लूप प्रोजेक्ट मेनू (फ़ोल्डर बटन) में “लूप प्रोजेक्ट सेव करें…” लूप को — उसके पार्ट 24-बिट FLAC के रूप में — उस पर बने हर अरेंजमेंट के साथ एक .unloop फ़ाइल के रूप में सेव करता है। “लूप प्रोजेक्ट खोलें…” उसे ठीक वैसा ही वापस लाता है। सेव करने से कोई फ़ाइल कभी ओवरराइट नहीं होती: जो नाम पहले से लिया हुआ हो, उसके साथ (2) जुड़ जाता है।","docs.projects.p2":"उसी मेनू में मौजूद लूप लाइब्रेरी आपके जोड़े गए फ़ोल्डरों के हर .unloop प्रोजेक्ट और हर WAV, AIFF, FLAC, MP3 और MIDI फ़ाइल की सूची दिखाती है, उसके बार, टेम्पो, टैग और यह कि वह कितनी बार अरेंज हुई है। इसमें खोजें और फ़िल्टर करें; किसी लूप को Unloop के अंदर सुनने के लिए उस पर क्लिक करें (तीर कुंजियाँ सूची में चलती हैं, Esc रोकता है), और जब वह ठीक एक लूप हो, तो उसे “अरेंज करें”। यह आपके फ़ोल्डरों को सिर्फ़ पढ़ती है। MIDI लूप अभी सूची में दिखते हैं और संस्करण 0.7.0 में अरेंज किए जा सकेंगे।","docs.projects.p3":"“लंबी फ़ाइल से लूप बनाएँ…” किसी लंबी रिकॉर्डिंग में से एक लूप काटता है: शुरुआती बार, 1, 2, 4, 8 या 16 बार की लंबाई और टेम्पो चुनें, कटे हुए हिस्से को बार-बार दोहराते हुए सुनें, फिर उसे एक नए लूप प्रोजेक्ट के रूप में “अरेंज करें”। फ़ाइल ख़ुद कभी नहीं बदलती।","docs.projects.p4":"हाल के प्रोजेक्ट में वे प्रोजेक्ट दिखते हैं जिन्हें आपने खोला या सेव किया, सबसे नया सबसे ऊपर। जो प्रोजेक्ट कहीं और चला गया हो, वह “नहीं मिला” के रूप में दिखता है, और “सूची से हटाएँ” सिर्फ़ पंक्ति हटाता है — फ़ाइल कभी नहीं।","docs.timeline.p1":"मैप पर हर क्लिप को आप संपादित कर सकते हैं। उसे चुनने के लिए क्लिक करें, ज़्यादा चुनने के लिए Shift-क्लिक करें या एक मार्की खींचें, या सबके लिए Ctrl/Cmd+A दबाएँ। क्लिप को स्नैप पर खिसकाने के लिए उसे खींचें (आज़ादी से खिसकाने के लिए Alt दबाए रखें), उसका आकार बदलने के लिए एक किनारा खींचें — लूप अपनी लंबाई के आगे दोहराता है — और उसकी सामग्री खिसकाने (स्लिप) के लिए उसके अंदर Alt-ड्रैग करें। S एडिट कर्सर पर विभाजित करता है।","docs.timeline.p2":"क्लिप के मेनू में — राइट-क्लिक, Shift+F10 या मेनू कुंजी से — “काटें”, “कॉपी करें”, “चिपकाएँ”, “बाद में क्लोन करें”, “उसी जगह प्रतिलिपि”, “हटाएँ”, “कर्सर पर विभाजित करें”, “उलटें”, “लॉक करें”, “योजना पर वापस”, “रंग” और “नाम बदलें…” हैं। अगर कोई क्लिप ऐसी लेन पर चिपकाई जाए जिस पर उसका पार्ट नहीं जा सकता, तो उसे वे लेन सुझाई जाती हैं जिन पर वह जा सकती है।","docs.timeline.p3":"बार, बीट, आठवें या सोलहवें नोट, उनके ट्रिपलेट पर स्नैप करें, या बिल्कुल नहीं; ज़ूम इन और आउट करें, या पूरे ट्रैक को फ़िट करें। जहाँ क्लिप मिलती हैं, वहाँ Unloop उन्हें 3 ms में क्रॉसफ़ेड करता है, और स्नैप बंद होने पर किनारा लूप के सबसे नज़दीकी ज़ीरो क्रॉसिंग पर आता है, इसलिए किसी भी संपादन से क्लिक नहीं होता।","docs.fades.p1":"क्लिप के हर सिरे पर तीन फ़ेड हैंडल होते हैं, जैसे Freally MIDI Master के सॉन्ग अरेंजमेंट में: लंबाई क्लिप के ऊपरी किनारे पर और वक्र ख़ुद फ़ेड पर। क्लिप की लंबाई चाहे जो हो, ये कभी एक-दूसरे को पार नहीं करते।","docs.fades.p2":"क्लिप का गेन हैंडल −∞ से +6 dB तक खींचें — बारीक चरणों के लिए Shift दबाए रखें, 0 dB के लिए डबल-क्लिक करें। कंसोल में हर पार्ट का एक फ़ेडर और एक मास्टर फ़ेडर है। खींचते समय हर बदलाव सुनाई देता है, और छोड़ने पर वह पूर्ववत का एक चरण बनता है।","docs.fades.p3":"कंसोल के फ़ेडर हर Freally ऐप की तरह काम करते हैं: −96 dB से +6 dB तक, डेसिबल में एकसमान, हर चरण 0.1 dB, पूरी रेंज 200 पिक्सेल में — Shift दबाए रखने पर गति उसकी एक-चौथाई हो जाती है। 0 dB के लिए फ़ेडर पर डबल-क्लिक या Alt-क्लिक करें; कीबोर्ड पर Page Up और Page Down उसे पूरे सफ़र का दसवाँ हिस्सा खिसकाते हैं, Home उसे सबसे नीचे और End सबसे ऊपर ले जाता है। फ़ेडर के नीचे की संख्या वह है जो आपने सेट किया; उसके बगल का मीटर दिखाता है कि क्या बज रहा है — −12 dBFS से नीचे हरा, −3 तक पीला, उसके ऊपर लाल — और उसकी क्लिप लाइट तब तक जलती रहती है जब तक आप उस पर क्लिक न करें।","docs.automation.p1":"“ऑटोमेशन” खोलें, एक पार्ट और उसमें बदलने वाली चीज़ चुनें, एक लेन जोड़ें और उस पर ड्रॉ करें। हर पार्ट में वॉल्यूम, पैन, चौड़ाई, लो-पास और हाई-पास कटऑफ़, रेज़ोनेंस, रीवर्ब और डिले सेंड, ड्राइव, क्रश, गेट की गहराई और पिच के लिए लेन होती हैं; मास्टर में वॉल्यूम और एक लो-पास होता है।","docs.automation.p2":"पॉइंट ड्रॉ करें, या उन्हें चुनकर खिसकाएँ; दो पॉइंट के बीच की रेखा मोड़ें; किसी रेंज पर एक आकार स्टैम्प करें — रैंप, S-कर्व, साइन, त्रिकोण, वर्ग या आरी, या रैंडम स्टेप — और किसी रेंज को कॉपी और पेस्ट करें। किसी मूव का अपना स्वीप या डाइव उसी लेन पर संपादित किया जा सकता है जिस पर वह बजता है। ऑटोमेशन सैंपल-दर-सैंपल पढ़ा जाता है, लाइव में भी और प्रिंट में भी।","docs.sections.p1":"किसी सेक्शन का नाम बदलने, उसका प्रकार या लंबाई बदलने, उसे पहले या बाद में ले जाने, उसके पहले या बाद में नया सेक्शन जोड़ने, उसे हटाने या लॉक करने के लिए उसके हेडर से उसका मेनू खोलें, या M दबाएँ। आप किसी सेक्शन को खींचकर उसका क्रम भी बदल सकते हैं: उसमें मौजूद सब कुछ उसके साथ जाता है।","docs.reroll.p1":"जो सेक्शन या क्लिप पसंद हो उसे लॉक करें, और “फिर से बनाएँ” बाकी को दोबारा बनाता है। यह किसी लॉक किए सेक्शन या आपकी संपादित क्लिप को कभी नहीं छूता, और किसी पड़ोसी को कभी नहीं खिसकाता। इसके बाद “क्या बदला” हर उस पार्ट और मूव की सूची दिखाता है जो इसने बदला, सेक्शन-दर-सेक्शन।","docs.reroll.p2":"“मूव जोड़ें” हर मूव की एक पैलेट खोलता है, जिसमें इस अरेंजमेंट के अपने मूव सबसे पहले होते हैं: एक मूव को मूव्स स्ट्रिप पर रखें, फिर उसे खींचें, फैलाएँ या हटाएँ। किसी मूव का इंस्पेक्टर खोलने के लिए उसे चुनें — उसकी शुरुआत, उसकी लंबाई, उसके पार्ट और उसकी अपनी सेटिंग, जैसे फ़िल्टर की रेंज या स्टटर के चरण — और प्रीव्यू चलते समय उसे “सुनें”।","docs.history.p1":"सॉन्ग अरेंजमेंट व्यू में हर बदलाव असीमित पूर्ववत और फिर से करने का एक चरण है। ऊपर के “पूर्ववत करें” और “फिर से करें” बटन उस चरण का नाम बताते हैं, या Ctrl/Cmd+Z और Ctrl/Cmd+Shift+Z (या Ctrl+Y) दबाएँ। इतिहास आपके DAW प्रोजेक्ट के साथ सेव होता है।","docs.history.p2":"हर बदलाव उसी पल आपके कंप्यूटर पर भी लिख दिया जाता है, इसलिए अगर आपका DAW सेव करने से पहले बंद हो जाए, तो प्रोजेक्ट आपके आख़िरी बदलाव के साथ फिर से खुलता है और यह बात बताता है। अगर वह बदलाव असल में किसी दूसरी कॉपी का था — “Save As” के बाद फिर से खोला गया कोई पुराना प्रोजेक्ट — तो “सहेजा गया संस्करण रखें” चुनें।","docs.shelf.p1":"अरेंजमेंट मेनू में उस लूप का हर अरेंजमेंट रहता है जो आपने खोला हुआ है: “नया अरेंजमेंट”, “प्रतिलिपि बनाएँ”, “नाम बदलें”, “हटाएँ”, “स्विच करें” — बजते समय अगले बार पर, रुके होने पर तुरंत — और “तुलना करें”, किन्हीं दो के बीच A/B। हर अरेंजमेंट चार स्नैपशॉट रखता है, A से D तक: किसी स्नैपशॉट को वापस लाने के लिए उस पर क्लिक करें, या मौजूदा अरेंजमेंट को वहाँ रखने के लिए Shift-क्लिक करें।","docs.shelf.p2":"“अरेंजमेंट निर्यात करें…” एक अरेंजमेंट को उसके लूप के बिना एक .unarr फ़ाइल के रूप में लिखता है। “अरेंजमेंट आयात करें…” उसे आपके खुले हुए लूप पर बिछाता है, हर सेक्शन, क्लिप, मूव और लेन को उसकी पहचान से ढूँढ़कर, और जिस चीज़ को जगह नहीं मिली उसकी सूची दिखाता है।","docs.midi.p1":"अरेंजमेंट को नोट्स के रूप में देखने के लिए हेडर में “MIDI” दबाएँ: टाइमलाइन पर हर क्लिप वे नोट्स दिखाती है जो उसका पार्ट बजाता है, और ड्रैग रैक का हर हैंडल — मिक्स, कोई पार्ट, कोई सेक्शन — अब ऑडियो के बजाय एक MIDI फ़ाइल ले जाता है। ऑडियो पर लौटने के लिए इसे फिर से दबाएँ। यह टॉगल सिर्फ़ वही बदलता है जो आप देखते और ड्रैग करते हैं: कोई क्लिप, सेक्शन, फ़ेड या मार्कर नहीं हिलता, और आपके पूर्ववत इतिहास में कुछ नहीं जुड़ता।","docs.midi.demo":"हेडर में “MIDI”: नोट्स के रूप में पढ़ा गया लूप, हर पार्ट को वैसे क्यों पढ़ा गया, और फिर से ऑडियो।","docs.midi.p2":"नोट्स आपके लूप से आते हैं। Unloop हर कैप्चर किए गए पार्ट को Freally MIDI Master के ऑडियो-से-MIDI रास्ते से नोट्स के रूप में पढ़ता है — पारंपरिक सिग्नल विश्लेषण, कोई AI नहीं — और इस दौरान आपका DAW काम करता रहता है। MIDI पैनल हर पार्ट की सूची दिखाता है और यह भी कि उसे ऐसे क्यों पढ़ा गया (ड्रम चैनल पर है, किट की तरह बजता है, सबसे निचली आवाज़, पिच के हिसाब से बँटा…), और साफ़-साफ़ बताता है कि यह रास्ता क्या नहीं कर सकता: यह ऑडियो से कोई काउंटर-मेलोडी नहीं लिखता, गाई गई लाइन नोट्स के रूप में नहीं लिखी जाती, कॉर्ड सरल रूप में लिखे जाते हैं, और किसी तेज़ हिट के नीचे छिपी हिट खो जाती है।","docs.midi.p3":"अगर आपके पास लूप MIDI में है, तो .mid फ़ाइल MIDI पैनल पर छोड़ें, या वहीं उसे चुनें: तब इस पार्ट के लिए उसके नोट्स इस्तेमाल होते हैं, ठीक वैसे ही बाँटकर जैसे Freally MIDI Master कोई फ़ाइल बाँटता है। फ़ाइल आपके प्रोजेक्ट के साथ रखी जाती है और डिस्क पर कभी नहीं बदली जाती। MIDI लूप ज़्यादा से ज़्यादा 40 KB का हो सकता है; “MIDI लूप हटाएँ” कैप्चर से पढ़े गए नोट्स पर वापस ले जाता है।","docs.midi.demoLoop":"MIDI पैनल पर चुना गया एक MIDI लूप, ड्रम, बेस और कॉर्ड्स में बाँटा गया, फिर हटाया गया।","docs.midi.p4":"मिक्स को ड्रैग करने पर पूरे गाने के लिए एक MIDI फ़ाइल मिलती है: हर पार्ट के लिए एक ट्रैक, उसी के नाम पर, ड्रम चैनल 10 पर, टेम्पो, और हर सेक्शन पर एक मार्कर। हर क्लिप के नोट्स उसके स्लिप, रिपीट और रिवर्स का पालन करते हैं। म्यूट, ड्रॉप-आउट या कट नोट्स हटा देते हैं, स्टटर या रोल उन्हें दोहराते हैं, हाफ़-टाइम उन्हें खींचकर लंबा करता है, और फ़िल्टर, वॉल्यूम, पैन और सेंड कंट्रोलर बन जाते हैं। जो मूव MIDI में कहा नहीं जा सकता — रिवाइंड, रिवर्स, लो-फ़ाई — वह फ़ाइल में एक मार्कर बन जाता है और मैप पर उसका एक बैज होता है; टेप स्टॉप या पिच डाइव एक पिच बेंड और एक मार्कर बन जाता है। वही सीड हमेशा वही फ़ाइल देता है।","docs.midi.p5":"“वेलॉसिटी डॉक्टर” हर पार्ट की वेलॉसिटी को सही तरह की बनाता है: ड्रम “स्तरीय” — हर हिट को एक्सेंट, मुख्य या घोस्ट में बाँटा जाता है, फिर उसके दायरे में रखा जाता है (100–127, 76–89 और 38–51, जब तक मॉडल कुछ और न कहे) — बेस और 808 “स्थिर” 127 पर, कॉर्ड्स “एकसमान” 96 पर और ऊपरी आवाज़ 6 ज़्यादा तेज़, मेलोडी “आकार दी गई”, यानी फ़्रेज़ के उठान के साथ अपने दायरे में, और काउंटर-मेलोडी उससे 12 कम। “मापी गई” नोट्स की अपनी वेलॉसिटी रखती है, और “आर्टिस्ट फ़ील” मॉडल की वेलॉसिटी इस्तेमाल करती है। हर बदलाव पूर्ववत का एक चरण है, और किसी लेन में कोई घोस्ट कभी किसी मुख्य हिट से तेज़ नहीं होती। “MIDI में फ़ेड” हर फ़ेड के साथ वेलॉसिटी को घटाता-बढ़ाता है, या आप चाहें तो उसे एक्सप्रेशन (CC11) के रूप में लिखता है।","docs.midi.demoDoctor":"“वेलॉसिटी डॉक्टर”: ड्रम “स्तरीय” से “स्थिर” पर, “मॉडल वाली लें” से वापस, फिर पूर्ववत और फिर से करें।","docs.keys.intro":"सॉन्ग अरेंजमेंट व्यू में हर संपादन बिना माउस के होता है। Unloop में यह सूची देखने के लिए <kbd>?</kbd> दबाएँ; Mac पर <kbd>Ctrl/⌘</kbd> का मतलब <kbd>⌘</kbd> है।","shortcutScope.everywhere":"हर जगह","shortcut.undo":"पूर्ववत करें","shortcut.redo":"फिर से करें","docs.keys.or":"या","shortcut.sheet":"शॉर्टकट की यह सूची दिखाएँ","shortcut.preview":"जब आपका DAW रुका हो तब प्रीव्यू चलाएँ या रोकें","shortcut.closeDialog":"डायलॉग, कार्ड या पैनल बंद करें","shortcutScope.timeline":"सॉन्ग अरेंजमेंट व्यू","shortcut.nextClip":"अगली क्लिप चुनें","shortcut.previousClip":"पिछली क्लिप चुनें","shortcut.clipAbove":"ऊपर वाली लेन की क्लिप चुनें","shortcut.clipBelow":"नीचे वाली लेन की क्लिप चुनें","shortcut.selectAll":"हर क्लिप चुनें","shortcut.deselect":"कुछ भी न चुनें, या खींचना छोड़ें","shortcut.moveEarlier":"चुनी हुई क्लिप को एक स्नैप पहले खिसकाएँ","shortcut.moveLater":"चुनी हुई क्लिप को एक स्नैप बाद में खिसकाएँ","shortcut.moveUp":"चुनी हुई क्लिप को ऊपर वाली लेन पर ले जाएँ","shortcut.moveDown":"चुनी हुई क्लिप को नीचे वाली लेन पर ले जाएँ","shortcut.endEarlier":"क्लिप को अंत से छोटा करें","shortcut.endLater":"क्लिप को अंत पर लंबा करें","shortcut.startEarlier":"क्लिप को शुरुआत पर लंबा करें","shortcut.startLater":"क्लिप को शुरुआत से छोटा करें","shortcut.gainUp":"क्लिप का गेन बढ़ाएँ","shortcut.gainDown":"क्लिप का गेन घटाएँ","shortcut.cursorEarlier":"एडिट कर्सर पहले ले जाएँ","shortcut.cursorLater":"एडिट कर्सर बाद में ले जाएँ","shortcut.split":"एडिट कर्सर पर विभाजित करें","shortcut.fades":"क्लिप के फ़ेड हैंडल पकड़ें","shortcut.reverse":"चुनी हुई क्लिप उलटें","shortcut.lock":"चुनी हुई क्लिप लॉक या अनलॉक करें","shortcut.copy":"चुनी हुई क्लिप कॉपी करें","shortcut.cut":"चुनी हुई क्लिप काटें","shortcut.paste":"एडिट कर्सर पर चिपकाएँ","shortcut.clone":"चयन के बाद क्लोन करें","shortcut.duplicate":"उसी जगह प्रतिलिपि बनाएँ","shortcut.delete":"चुनी हुई क्लिप या चुना हुआ मूव हटाएँ","shortcut.clipMenu":"क्लिप का मेनू खोलें","shortcut.sectionMenu":"सेक्शन का मेनू खोलें","shortcutScope.fades":"फ़ेड हैंडल पकड़े रहने पर","shortcut.fadeLonger":"फ़ेड को एक स्नैप लंबा करें","shortcut.fadeShorter":"फ़ेड को एक स्नैप छोटा करें","shortcut.fadeCurveUp":"फ़ेड का वक्र ऊपर मोड़ें","shortcut.fadeCurveDown":"फ़ेड का वक्र नीचे मोड़ें","shortcut.fadeOtherSide":"दूसरे फ़ेड पर जाएँ","shortcut.fadeDone":"फ़ेड हैंडल छोड़ें","shortcutScope.fader":"फ़ेडर पर","shortcut.faderUp":"फ़ेडर एक चरण ऊपर करें","shortcut.faderDown":"फ़ेडर एक चरण नीचे करें","shortcut.faderBigUp":"फ़ेडर को उसकी दूरी का दसवाँ हिस्सा ऊपर करें","shortcut.faderBigDown":"फ़ेडर को उसकी दूरी का दसवाँ हिस्सा नीचे करें","shortcut.faderTop":"फ़ेडर सबसे ऊपर","shortcut.faderOff":"फ़ेडर बंद","shortcutScope.lane":"ऑटोमेशन लेन पर","shortcut.pointsDelete":"चुने हुए पॉइंट हटाएँ","shortcut.pointsCancel":"खींचना छोड़ें","shortcutScope.search":"खोज में","shortcut.searchNext":"अगला परिणाम","shortcut.searchPrevious":"पिछला परिणाम","shortcut.searchPick":"परिणाम चुनें","shortcut.searchClose":"परिणाम बंद करें","shortcutScope.menu":"मेनू में","shortcut.menuNext":"अगला आइटम","shortcut.menuPrevious":"पिछला आइटम","shortcut.menuClose":"मेनू बंद करें","docs.sounds.p1":"सेटिंग्स, कोई मेनू या डायलॉग खोलना या बंद करना, और Loop Library को दिखाना या छिपाना, हर एक एक छोटी ध्वनि बजाता है — हर Freally ऐप में वही ध्वनियाँ — जो ठीक उतनी देर चलती है जितनी स्क्रीन पर हरकत। ये आपके DAW में Unloop के अपने आउटपुट से बजती हैं, कभी आपके गीत में नहीं जातीं: न किसी Print में, न कैप्चर, स्टेम, ड्रैग या ऑफ़लाइन बाउंस में। सेटिंग्स में आप इन्हें बंद कर सकते हैं, इनका स्तर बदल सकते हैं, या «प्लेबैक के दौरान शांत» चालू रख सकते हैं (शुरुआत में चालू रहता है), ताकि आपका DAW या प्रीव्यू चलते समय ये चुप रहें। यदि आपके सिस्टम में कम गति चालू है, तो कुछ नहीं हिलता और इनके बजाय एक छोटी टिक बजती है।","docs.sounds.demo":"सेटिंग्स में इंटरफ़ेस ध्वनियाँ: चालू या बंद, उनका स्तर, और «प्लेबैक के दौरान शांत»।","docs.sounds.p2":"स्टैंडअलोन ऐप में टाइटल बार थीम का अनुसरण करती है — डार्क थीम में गहरी, लाइट थीम में हल्की — और उसमें कोई शीर्षक नहीं होता, क्योंकि विंडो के ऊपर घूमता हुआ नाम ही शीर्षक है। DAW के भीतर प्लगइन विंडो DAW की होती है और उसका शीर्षक बना रहता है।","docs.look.p1":"Unloop में दो थीम हैं, गहरी और हल्की, Freally हरे रंग पर; “सेटिंग्स” में “गहरा”, “हल्का” या “सिस्टम” चुनें, जो आपके कंप्यूटर का अनुसरण करता है। इसके फ़ेडर, नॉब और मीटर, “जनरेट करें”, “फिर से बनाएँ” और “प्रिंट” कुंजियाँ, और स्लाइडर व स्विच Freally परिवार के हैं — Freally Flipcopy वाले ही कंट्रोल, हर थीम के लिए रेंडर किए गए — इसलिए हर Freally ऐप एक जैसा दिखता है और दबाने में एक जैसा लगता है।","docs.look.demo":"“फिर से बनाएँ” दबाना और एक फ़ेडर खिसकाना, फिर “हल्का”, “गहरा” और “सिस्टम”।","docs.look.p2":"“सेटिंग्स” में “मोशन” के दो विकल्प हैं। “स्पीड”: “तेज़” ऊपर के नाम को दोगुनी तेज़ी से घुमाता है। “कम मोशन”: “कम करें” नाम को सपाट कर देता है और हर एनिमेशन रोक देता है; “सिस्टम के अनुसार” भी यही करता है, जब भी आपका कंप्यूटर कम मोशन माँगता है।","docs.look.demoMotion":"“तेज़” ऊपर के नाम को और तेज़ी से घुमाता है; “कम करें” उसे सपाट कर देता है।","docs.privacy.p1":"Unloop में न कोई खाता है, न टेलीमेट्री, और प्लगइन व स्टैंडअलोन ऐप में बिल्कुल भी नेटवर्किंग कोड नहीं है। आपके लूप, आपके प्रोजेक्ट और आपके ट्रैक कभी आपके कंप्यूटर से बाहर नहीं जाते, और नेटवर्क ड्राइव पर रखा कोई लूप, प्रोजेक्ट या एक्सपोर्ट फ़ोल्डर, उस पर कुछ भी छुए जाने से पहले ही अस्वीकार कर दिया जाता है।","docs.privacy.p2":"यह अपनी फ़ाइलें आपके ऐप-डेटा फ़ोल्डर में रखता है (Windows पर %APPDATA%\\Freally Unloop): लाइसेंस पर आपका जवाब, आपकी प्राथमिकताएँ, हाल के प्रोजेक्ट, लूप लाइब्रेरी का इंडेक्स, कैप्चर कैश (अधिकतम 2 GB) और वे फ़ाइलें जिनके ज़रिए इंस्टेंस मिलते हैं। यह आपके लूप फ़ोल्डरों में कभी कुछ नहीं लिखता; एक्सपोर्ट और प्रोजेक्ट वहीं जाते हैं जहाँ आप चुनते हैं।","docs.privacy.p3":"इसमें किसी भी तरह का AI नहीं है: हर अरेंजमेंट की योजना शोध किए हुए अरेंजमेंट डेटा पर नियतात्मक नियमों से बनती है और उसे पारंपरिक सिग्नल प्रोसेसिंग से बजाया जाता है, और अगर कभी कोई मशीन-लर्निंग लाइब्रेरी जोड़ी जाए तो एक बिल्ड गेट फ़ेल हो जाता है।","docs.report.p1":"जब Unloop खुद विफल होता है — अपनी कोई फ़ाइल नहीं लिख सका, कोई एक्सपोर्ट या ड्रैग गड़बड़ हो गया, जिस लूप को पढ़ना था वह पढ़ा नहीं जा सका, या विंडो क्रैश हो गई — तो त्रुटि में एक «रिपोर्ट» बटन होता है। यह आपके ब्राउज़र में रिपोर्ट पेज खोलता है, जिसमें तथ्य पहले से भरे होते हैं: वह कहाँ विफल हुआ, संस्करण और आपका सिस्टम, हस्ताक्षरित ताकि उन्हें बदला न जा सके। आप लिखते हैं कि क्या हुआ, और जब तक आप वहाँ भेजें नहीं दबाते, कुछ नहीं भेजा जाता। Unloop खुद कुछ नहीं भेजता।","docs.report.p2":"यदि Unloop क्रैश हुआ था, तो अगली बार खुलने पर वह एक बार रिपोर्ट करने की पेशकश करता है; «बंद करें» उसे भूल जाता है। जो त्रुटि केवल आपके अनुरोध को मना करती है — ऐसा नाम जो फ़ाइल नहीं बन सकता, ऐसा फ़ोल्डर जो है ही नहीं — उसमें «रिपोर्ट» बटन नहीं होता। केवल रिलीज़ बिल्ड ही रिपोर्ट बना सकते हैं।","docs.limits.key":"लूप का स्केल अभी पढ़ा नहीं जाता, इसलिए डिफ़ॉल्ट फ़ाइल नामों में स्केल शामिल नहीं होता।","docs.limits.picture":"ड्रैग करते समय अभी उस चीज़ की कोई तस्वीर नहीं दिखती जिसे आप ड्रैग कर रहे हैं।","docs.limits.throw":"आख़िरी बार पर रिवर्ब या डिले थ्रो ट्रैक की आख़िरी बार लाइन पर कट जाता है; प्रिंट उसके आगे गूँजता नहीं रहता।","docs.limits.display":"अलग डिस्प्ले स्केल वाले दूसरे मॉनिटर पर, एडिटर अपना आकार मुख्य डिस्प्ले के हिसाब से तय करता है।","docs.limits.hands":"Unloop को अभी हर DAW में, हर सिस्टम पर हाथ से पूरी तरह परखा नहीं गया है। यह काम रिलीज़ कैंडिडेट का है, 1.0.0 से पहले।","kit.skip":"सामग्री पर जाएँ","kit.nav.site":"साइट","kit.nav.home":"होम","kit.nav.features":"फ़ीचर्स","kit.nav.documentation":"दस्तावेज़ीकरण","kit.nav.changelog":"बदलाव लॉग","kit.nav.language":"भाषा","kit.nav.allApps":"सभी Freally ऐप्स","kit.badge.progress":"v0.7.0 पूरा · आगे v0.8.0","kit.cta.features":"सभी फ़ीचर्स देखें","kit.cta.docs":"दस्तावेज़ीकरण पढ़ें","kit.price":"Freally Unloop आज मुफ़्त है, लेकिन हो सकता है कि यह हमेशा मुफ़्त न रहे: भविष्य के संस्करण बेचे जा सकते हैं।","kit.noDownloads":"अभी कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","kit.label.overview":"अवलोकन","kit.label.inside":"अंदर","kit.label.roadmap":"रोडमैप","kit.ladder.done":"पूरा","kit.ladder.planned":"नियोजित","kit.ladder.goal":"लक्ष्य","kit.ladder.later":"बाद में","kit.label.honesty":"ईमानदारी","kit.family.label":"Freally परिवार","kit.family.title":"<span class=\"hl-muted\">एक परिवार।</span> <span class=\"hl-bright\">आठ ऐप्स।</span>","kit.cta.label":"क्या बदला","kit.cta.title":"<span class=\"hl-muted\">हर संस्करण,</span> <span class=\"hl-bright\">लिखित में।</span>","kit.cta.lede":"बदलाव लॉग में Freally Unloop में हुआ हर बदलाव, संस्करण-दर-संस्करण, सभी अठारह भाषाओं में दर्ज है।","kit.cta.changelog":"बदलाव लॉग पढ़ें","kit.footer.thisApp":"यह ऐप","kit.footer.family":"Freally परिवार","kit.status.devVersion":"विकास में · v0.7.0","kit.head.features":"<span class=\"hl-muted\">यह जो कुछ करता है,</span> <span class=\"hl-bright\">आमने-सामने।</span>","kit.label.numbers":"आँकड़ों में","kit.numbers.lead":"हर आँकड़ा ऐप से ही गिना गया है। कुछ भी अनुमानित नहीं है, और कुछ भी बढ़ाकर पूर्णांकित नहीं किया गया है।","kit.label.free":"आज मुफ़्त","kit.label.compare":"तुलना","kit.label.principles":"सिद्धांत","kit.label.limits":"सीमाएँ","kit.states.title":"स्थितियों का अर्थ","kit.states.done":"बना और टैग किया गया, पर इस साइट पर डाउनलोड नहीं","kit.states.planned":"अभी बनना बाकी है","kit.states.goal":"वह संस्करण जिस तक यह रास्ता जाता है","kit.states.later":"उसके बाद, और अभी तय नहीं","kit.states.ladder":"रास्ते का हर पड़ाव देखें","kit.head.documentation":"<span class=\"hl-muted\">यह कैसे काम करता है,</span> <span class=\"hl-bright\">क़दम-दर-क़दम।</span>","kit.search.placeholder":"दस्तावेज़ीकरण में खोजें","kit.docs.contents":"विषय-सूची","kit.head.changelog":"<span class=\"hl-muted\">हर बदलाव,</span> <span class=\"hl-bright\">संस्करण-दर-संस्करण।</span>","kit.changelog.lede":"सबसे नया पहले: Freally Unloop में जो कुछ बदला, इस साइट की हर भाषा में।","kit.changelog.versions":"संस्करण","kit.changelog.unreleased":"अप्रकाशित","kit.search.none":"इस साइट पर इससे कुछ भी मेल नहीं खाता।","kit.zoom.close":"बंद करें","changelog.69c6a54708de":"<span class=\"release__meta\"><span class=\"release__ver\">अप्रकाशित</span></span>","changelog.6b02e0d363a4":"जोड़ा गया","changelog.235b3002ec6a":"<strong>मैनुअल में फ़ीचर वीडियो</strong> — छह छोटे, बिना आवाज़ वाले वीडियो जो अपने अध्यायों के पास लूप में चलते हैं, असली ऐप में फ़िल्माए गए: थीम और कंसोल के कंट्रोल, मोशन, इंटरफ़ेस ध्वनियाँ, MIDI व्यू, एक MIDI लूप और वेलॉसिटी डॉक्टर। <code>npm run showcase</code> इन्हें स्टैंडअलोन ऐप के रिलीज़ बिल्ड से, उसकी अपनी अलग प्रोफ़ाइल पर, एक बनाए गए कर्सर के साथ फ़िल्माता है।","changelog.fe24ca64593e":"<span class=\"release__meta\"><span class=\"release__ver\">v0.7.0</span><time class=\"release__date\" datetime=\"2026-10-06\">2026-10-06</time></span><span class=\"release__title\">X: MIDI सपोर्ट</span>","changelog.53632228602f":"व्यू को <strong>MIDI</strong> पर पलटें और वही अरेंज किया हुआ ट्रैक एक मल्टी-ट्रैक MIDI गाने के रूप में ड्रैग करके बाहर निकालें। नोट्स आपके लूप से आते हैं, जिन्हें Freally MIDI Master का ऑडियो-से-MIDI रास्ता पढ़ता है (उसमें कहीं कोई AI नहीं), या उस MIDI लूप से जिसे आप इंस्टेंस पर छोड़ते हैं। हर मूव, फ़ेड और सेक्शन ईमानदारी से फ़ाइल में पहुँचता है, और हर पार्ट की वेलॉसिटी सही तरह की रखी जाती है। <code>0.6.7</code>, यानी नया रूप-रंग, इसी टैग के अंदर आता है।","changelog.a685ef77c77e":"<strong>ऑडियो/MIDI टॉगल</strong> — हेडर में <strong>MIDI</strong> चिप। दबाने पर लेन हर क्लिप के नोट्स दिखाती हैं और हर ड्रैग हैंडल (मिक्स, कोई रोल, कोई सेक्शन) WAV के बजाय एक Standard MIDI File ले जाता है। यह सिर्फ़ व्यू बदलता है, और कुछ नहीं: कोई क्लिप, सेक्शन, फ़ेड या मार्कर नहीं हिलता, और पूर्ववत अछूता रहता है।","changelog.3678409fa0f5":"<strong>MIDI सॉन्ग टेम्पलेट</strong> — एक टाइप 1 फ़ाइल: टेम्पो, टाइम सिग्नेचर और हर सेक्शन के एक मार्कर वाला कंडक्टर ट्रैक, फिर हर पार्ट का एक ट्रैक, पार्ट के नाम पर, ड्रम चैनल 10 पर। हर क्लिप के नोट्स उसके स्लिप, रिपीट और रिवर्स का पालन करते हैं। म्यूट, ड्रॉप-आउट या कट नोट्स हटा देते हैं, स्टटर या रोल उन्हें धीरे-धीरे बदलती वेलॉसिटी के साथ दोहराते हैं, और हाफ़-टाइम उन्हें खींचकर लंबा करता है। फ़िल्टर, वॉल्यूम, पैन और सेंड कंट्रोलर बन जाते हैं। वही सीड वही बाइट्स देता है, और MIDI प्लान ही ऑडियो प्लान है — एक ही टाइलिंग।","changelog.0a2c62524710":"<strong>MIDI जो नहीं कह सकता, उसके बारे में ईमानदार।</strong> जिस मूव का MIDI में कोई अर्थ नहीं (रिवाइंड, रिवर्स, लो-फ़ाई), वह फ़ाइल में एक मार्कर और मैप पर एक बैज है। जिस मूव को MIDI सिर्फ़ अनुमान से दिखा सकता है (टेप स्टॉप, पिच डाइव), वह एक पिच बेंड और एक मार्कर है, जिसका ज़िक्र उसके टूलटिप में होता है। MIDI पैनल इन्हें गिनता है।","changelog.2f6d8f5bc65d":"<strong>MIDI में फ़ेड</strong> — फ़ेड अपने नीचे आने वाले नोट्स की वेलॉसिटी को उसी कर्व पर घटाता-बढ़ाता है जिस पर ऑडियो चलता है, या आप चुनें तो CC11 एक्सप्रेशन लिखता है और वेलॉसिटी को जस का तस छोड़ देता है।","changelog.98ada9ac57ad":"<strong>वेलॉसिटी डॉक्टर</strong> — हर पार्ट के लिए: <em>मापी गई</em>, <em>स्तरीय</em> (हर ड्रम हिट को एक्सेंट, मुख्य या घोस्ट में बाँटकर उसके दायरे में रखा जाता है, डिफ़ॉल्ट रूप से 100–127 / 76–89 / 38–51), <em>स्थिर</em> (बेस और 808: 127), <em>एकसमान</em> (कॉर्ड्स: 96, ऊपरी आवाज़ +6), <em>आकार दी गई</em> (मेलोडी फ़्रेज़ के उठान के साथ अपने दायरे में, काउंटर 12 कम) और <em>आर्टिस्ट फ़ील</em>। डिफ़ॉल्ट मॉडल तय करता है; हर बदलाव पूर्ववत का एक चरण है। किसी लेन में कोई घोस्ट कभी किसी मुख्य हिट से तेज़ नहीं बजती।","changelog.beacae11ad48":"<strong>एक्सट्रैक्शन पैनल</strong> — हर पार्ट, और उसे जिस वजह से वहाँ भेजा गया (ड्रम चैनल पर है, किट की तरह बजता है, सबसे निचली आवाज़, पिच के हिसाब से बँटा…)। यह रास्ते की सीमाएँ भी बताता है: <em>ऑडियो से काउंटर-मेलोडी नहीं — MIDI Master एक लिख सकता है</em>; <em>गाई गई लाइन मिली — MIDI के रूप में नहीं लिखी गई</em>; <em>कॉर्ड सरल रूप में</em>; किसी तेज़ हिट के नीचे छिपी हिट खो जाती है। पार्ट एक वर्कर पर पढ़े जाते हैं, DAW के एडिटर थ्रेड पर कभी नहीं।","changelog.4ce2e3c2d9c9":"<strong>MIDI लूप इनपुट</strong> — इंस्टेंस पर एक <code>.mid</code> छोड़ें (या कोई चुनें) और उसके नोट्स उस पार्ट के लिए इस्तेमाल होते हैं, ठीक वैसे ही बाँटकर जैसे Freally MIDI Master उन्हें बाँटता है। फ़ाइल लूप प्रोजेक्ट के साथ रखी जाती है, डिस्क पर कभी नहीं बदली जाती, और अगर वह MIDI न हो या किसी लूप से कहीं ज़्यादा बड़ी हो तो अस्वीकार कर दी जाती है।","changelog.2a6141e43be0":"बदला गया","changelog.fda5c310c48e":"<strong>लूप प्रोजेक्ट अब स्कीमा 7 हैं</strong>: वे MIDI व्यू, MIDI लूप और वेलॉसिटी के चुनाव रखते हैं। स्कीमा 6 का प्रोजेक्ट ऑडियो व्यू में मॉडल की वेलॉसिटी के साथ खुलता है। रसीद अब बताती है कि कौन-सा फ़ॉर्मैट एक्सपोर्ट हुआ, और MIDI फ़ाइल के लिए यह भी कि उसमें क्या था (पूरा गाना, एक पार्ट या एक सेक्शन) और उसके फ़ेड कैसे लिखे गए।","changelog.f91711134ed7":"<strong>संपर्क हर जगह freallyproducts@gmail.com है</strong> (लाइसेंस, EULA, सुरक्षा नीति, DAW में दिखने वाली प्लगइन की जानकारी, crate मेटाडेटा)।","changelog.8f6fb4eb7f42":"सुरक्षा","changelog.fed181492a71":"<strong>छोड़े गए MIDI लूप की सीमा तय है</strong>: 40 KB से बड़ा होने पर वह अस्वीकार होता है — भेजे जाने से पहले पेज द्वारा और डिकोड होने से पहले प्लगइन द्वारा — <code>engine</code> के रीडर से पार्स किया जाता है, और सिर्फ़ लूप प्रोजेक्ट में रखा जाता है।","changelog.3245771bf860":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.7</span><time class=\"release__date\" datetime=\"2026-10-06\">2026-10-06</time></span><span class=\"release__title\">L: रूप-रंग</span>","changelog.fefa33078646":"Unloop अब Freally परिवार के बाकी ऐप्स की तरह दिखता है और दबाने में वैसा ही लगता है। इसकी कुंजियाँ, फ़ेडर, नॉब, मीटर, स्लाइडर और स्विच Freally Flipcopy के हैं, और Freally हरे रंग पर इसकी हल्की और गहरी थीम भी — जैसी हैं वैसी ही कॉपी की गईं, यहाँ कभी दोबारा नहीं बनाई गईं। <code>0.7.0</code> के अंदर शिप हुआ; इस पायदान का अपना कोई टैग नहीं है।","changelog.1a85ec8906e7":"<strong>मोशन सेटिंग्स</strong> — <em>स्पीड</em> (<em>सामान्य</em> या <em>तेज़</em>: तेज़ शीर्षक को दोगुनी तेज़ी से घुमाता है; पॉपओवर या पैनल की हरकत उतनी ही लंबी रहती है जितनी उसकी ध्वनि) और <em>कम मोशन</em> (<em>सिस्टम के अनुसार</em> या <em>कम करें</em>: कम करें शीर्षक को सपाट कर देता है और हर एनिमेशन रोक देता है)।","changelog.9c41afd00587":"<strong>रूप-रंग Freally Flipcopy का है, कॉपी किया गया, कभी दोबारा नहीं बनाया गया।</strong> कंसोल के फ़ेडर, नॉब और मीटर, उसकी “जनरेट करें”, “फिर से बनाएँ” और “प्रिंट” कुंजियाँ, और सेटिंग्स का स्लाइडर और स्विच Flipcopy के कंपोनेंट हैं, जो Freally प्लेबुक के Blender रेंडर दिखाते हैं, एक हल्के सेट और एक गहरे सेट में। बाकी हर बटन एक सादा, लेबल वाला बटन ही रहता है, और प्रीव्यू के प्ले, स्टॉप और लूप सादे आइकन बटन हैं। एक गेट हर कॉपी की गई फ़ाइल को बाइट-दर-बाइट Flipcopy की फ़ाइल जैसा बनाए रखता है।","changelog.db68ef6fbf09":"<strong>दो थीम, हल्की और गहरी, Freally हरे रंग पर</strong> (<code>#79d920</code>), साझा Freally UI किट से जिसे Flipcopy इस्तेमाल करता है: उसकी पृष्ठभूमियाँ, काँच के पैनल, चेसिस और चमक। कंसोल थीम का अनुसरण करता है, और उसके लैंपों के दिन के उजाले वाले अपने रंग हैं। हर रंग-जोड़ी दोनों थीम में WCAG 2.1 AA पास करती है। कोई स्किन नहीं (मालिक, 2026-10-06)।","changelog.26c72febc5d6":"<strong>फ़ेडर परिवार के बाकी ऐप्स की तरह काम करते हैं</strong>: −96 से +6 dB, dB में एकसमान, हर चरण 0.1 dB, पूरी रेंज 200 पिक्सेल में (<code>Shift</code> से उसकी एक-चौथाई गति), डबल-क्लिक या <code>Alt</code>-क्लिक से वापस 0 dB, <code>Page Up</code>/<code>Page Down</code> से सफ़र का दसवाँ हिस्सा, <code>Home</code> से सबसे नीचे और <code>End</code> से सबसे ऊपर। कैप वह दिखाता है जो आपने सेट किया, और उसके बगल का मीटर वह दिखाता है जो बज रहा है।","changelog.af98a3123c11":"<strong>मीटर Flipcopy के हैं</strong>: −12 dBFS से नीचे हरा, −3 तक पीला, उसके ऊपर लाल, और 0 dBFS पर एक क्लिप लाइट जो तब तक जलती रहती है जब तक आप उस पर क्लिक न करें।","changelog.9d58c6cb4f8a":"<strong>सेटिंग्स में ध्वनियों का स्विच अब चालू/बंद स्विच है</strong>, Flipcopy वाला, और उनका स्तर Flipcopy का स्लाइडर है।","changelog.e817b93164f2":"<strong>एडिटर के पेज इनलाइन स्टाइल की अनुमति देते हैं</strong> (<code>style-src 'self' 'unsafe-inline'</code>)। Flipcopy का हार्डवेयर सेट हर रेंडर का पता पेज की अपनी एक स्टाइलशीट में घोषित करता है, और वह पता इस पर निर्भर करता है कि पेज कहाँ से सर्व हो रहा है, इसलिए कोई हैश उसे पक्का नहीं कर सकता। स्क्रिप्ट अब भी सिर्फ़ <code>'self'</code> हैं, और कुछ और ढीला नहीं किया गया।","changelog.282953e12efa":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.5</span><time class=\"release__date\" datetime=\"2026-10-05\">2026-10-05</time></span><span class=\"release__title\">U: ध्वनियाँ, टाइटल बार और रिपोर्ट करें</span>","changelog.87ee3a6f936b":"Unloop अब Freally परिवार के बाकी ऐप्स की तरह सुनाई देता और दिखता है, और जब वह विफल होता है, तो ऐसे बताता है कि आप उसकी रिपोर्ट कर सकें। कोई पॉपओवर या डायलॉग खोलना और Loop Library दिखाना, हर एक परिवार की अपनी छोटी ध्वनि बजाता है, ठीक उतनी ही देर जितनी हरकत चलती है; स्टैंडअलोन ऐप की टाइटल बार डार्क मोड में गहरी है, बिना शीर्षक के; और जो त्रुटि Unloop की अपनी गलती है, वह <strong>रिपोर्ट</strong> का विकल्प देती है।","changelog.9be25b6e3986":"<strong>इंटरफ़ेस ध्वनियाँ</strong> — Freally परिवार का एक ही सेट, <em>कोमल, काँच जैसी</em>, हर Freally ऐप में वही फ़ाइलें: कोई पॉपओवर या डायलॉग खुलना और बंद होना (सेटिंग्स और हेडर तथा कंसोल का हर पॉपओवर, रोल और बस पैनल, प्रोजेक्ट मेनू, एक्सपोर्ट डायलॉग, शॉर्टकट शीट) और Loop Library का दिखना और छिपना। हर ध्वनि ठीक उतनी देर चलती है जितनी उसकी हरकत; दोनों एक ही टाइमिंग तालिका पढ़ती हैं। ये Unloop के अपने आउटपुट से बजती हैं — कभी DAW को दरकिनार कर पीसी के स्पीकरों से नहीं — और कभी रिकॉर्ड में नहीं जातीं: न किसी Print में, न कैप्चर, स्टेम या ड्रैग-आउट में, न ऑफ़लाइन बाउंस में, न बायपास के दौरान। डिफ़ॉल्ट रूप से चालू; सेटिंग्स में उनका स्विच, उनका स्तर और <em>प्लेबैक के दौरान शांत</em> (चालू) है। कम गति वाले मोड में इनके बजाय एक छोटी टिक बजती है।","changelog.d21989d83caf":"<strong>पॉपओवर, डायलॉग और Loop Library हिलते हैं</strong> — वे परिवार की हरकतों के साथ खुलते और बंद होते हैं (Loop Library अपने किनारे से सरककर आती है, दाएँ से बाएँ लिखी जाने वाली भाषा में दूसरी ओर से); कम गति वाले मोड में वे तुरंत दिखते हैं।","changelog.598761b72492":"<strong>स्टैंडअलोन ऐप की टाइटल बार डार्क मोड में गहरी है</strong> और थीम का तुरंत अनुसरण करती है, और उसमें कोई शीर्षक नहीं होता — घूमता हुआ वर्डमार्क ही शीर्षक है। DAW के भीतर प्लगइन विंडो का शीर्षक DAW का ही रहता है।","changelog.01213ea06966":"<strong>रिपोर्ट करें।</strong> जब Unloop खुद विफल होता है — अपनी कोई फ़ाइल जिसे वह लिख नहीं सका, कोई एक्सपोर्ट या ड्रैग जिसे वह बना नहीं सका, कोई लूप जिसे वह पढ़ नहीं सका, अपने ही पेज की कोई कॉल जिसे वह पढ़ नहीं सका, पेज का क्रैश होना — तो त्रुटि <strong>रिपोर्ट</strong> का विकल्प देती है, जो आपके ब्राउज़र में रिपोर्ट पेज खोलता है, तथ्यों के साथ भरा हुआ (वह कहाँ विफल हुआ, संस्करण, सिस्टम), हस्ताक्षरित ताकि उन्हें बदला न जा सके। जब तक आप वहाँ भेजें नहीं दबाते, कुछ भी नहीं भेजा जाता। क्रैश अगली बार Unloop खुलने पर एक बार पेश किया जाता है। आपने जो माँगा उसे अस्वीकार करने पर कभी रिपोर्ट का विकल्प नहीं आता, और केवल रिलीज़ बिल्ड ही रिपोर्ट बना सकते हैं।","changelog.a23b97bb00ba":"<strong>Freally MIDI Master का हर साझा crate <code>shared-v10</code> पर चला गया</strong> (<code>shared-v5</code> से; <code>freally-report</code> <code>shared-v7</code> से)। रोस्टर डेटा नहीं बदला, लेकिन किसी प्लान का डेटासेट संस्करण टैग का नाम लेता है, इसलिए उसके साथ हर प्लान हैश बदल गया — यह केवल स्नैपशॉट की हेडर पंक्तियों में एक golden बदलाव है।","changelog.80b45d96b56e":"<strong>ऐप आईडी <code>com.freallyproducts.unloop</code> है</strong> (पहले <code>com.mikeweaver.freally-unloop</code> थी): किसी पुराने प्री-रिलीज़ से सहेजा गया DAW प्रोजेक्ट पुरानी आईडी खोजता है और प्लगइन नहीं ढूँढ पाएगा। अभी तक कुछ भी रिलीज़ नहीं हुआ है।","changelog.07fa6f54161c":"<strong>1.0 की राह में एक पायदान जुड़ा</strong>: स्किन और हार्डवेयर सेट <code>v0.6.7</code> में चले गए हैं, जो मालिक के Freally Flipcopy में स्वीकृत करने के बाद उन्हें वहाँ से कॉपी करेगा।","changelog.c4b898d0a012":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.0</span><time class=\"release__date\" datetime=\"2026-10-01\">2026-10-01</time></span><span class=\"release__title\">T: टाइमलाइन</span>","changelog.0a8e4d670c30":"अरेंजमेंट का हर हिस्सा अब आप संपादित कर सकते हैं, और हर आउटपुट ठीक वही सुनाता है जो आपने संपादित किया। क्लिप को खिसकाएँ, कॉपी करें, पेस्ट करें, क्लोन करें, उनका आकार बदलें, उनकी सामग्री खिसकाएँ (स्लिप) और उन्हें विभाजित करें; MIDI Master के तीन हैंडल से फ़ेड बनाएँ; क्लिप, पार्ट और मास्टर फ़ेडर चलाएँ; ऑटोमेशन ड्रॉ करें; सेक्शन को नया आकार दें; जो पसंद हो उसे लॉक करें और बाकी को फिर से बनाएँ; मूव्स हाथ से रखें — हर बदलाव पूर्ववत का एक चरण, जिसे आप जितना चाहें पूर्ववत करें और फिर से करें। किसी लूप के प्रोजेक्ट में अब अरेंजमेंट की एक शेल्फ़ रहती है, जिनके बीच आप अगले बार पर बदल सकते हैं, और एक अरेंजमेंट <code>.unarr</code> फ़ाइल के रूप में अकेले भी कहीं ले जाया जा सकता है।","changelog.b5f9159dff5a":"<strong>टाइमलाइन।</strong> मैप पर हर क्लिप संपादित की जा सकती है: चुनें (क्लिक, <code>Shift</code>, मार्की, <code>Ctrl/Cmd+A</code>), खिसकाएँ (स्नैप पर; <code>Alt</code> उसे दरकिनार करता है; लेन सिर्फ़ उन पार्ट के बीच बदलती है जो एक लेन साझा कर सकते हैं), हटाएँ, चयन के बाद क्लोन करें (<code>Ctrl/Cmd+D</code>), उसी जगह प्रतिलिपि बनाएँ (<code>Shift+D</code>), कॉपी करें, काटें और एडिट कर्सर पर चिपकाएँ (असंगत लेन होने पर वे लेन सुझाई जाती हैं जिन पर क्लिप जा सकती है, चुपचाप कुछ नहीं बदला जाता), किसी भी किनारे से आकार बदलें (लूप अपनी लंबाई के आगे दोहराता है), सामग्री खिसकाएँ (<code>Alt</code>-ड्रैग), विभाजित करें (<code>S</code>), उलटें, नाम बदलें, रंग दें और <em>योजना पर वापस</em> — कॉन्टेक्स्ट मेनू से भी। खिसकाई गई, सामग्री-खिसकाई गई या उलटी क्लिप कैप्चर किए गए लूप में अपनी ही जगह से सुनाई देती है।","changelog.91d85c02a166":"<strong>फ़ेड, ठीक MIDI Master के सॉन्ग अरेंजमेंट की तरह</strong>: हर तरफ़ तीन हैंडल — लंबाई क्लिप के ऊपरी किनारे पर, वक्रता फ़ेड की रेखा पर — जो क्लिप की किसी भी लंबाई पर कभी एक-दूसरे को पार नहीं करते; सबसे छोटी क्लिप 64वें नोट की होती है।","changelog.c0ccdbacbd8c":"<strong>फ़ेडर।</strong> क्लिप पर एक गेन हैंडल (−∞ से +6 dB, <code>Shift</code> से बारीक, डबल-क्लिक से वापस 0 dB), कंसोल के पार्ट फ़ेडर और एक मास्टर फ़ेडर — सब एक ही फ़ेडर लॉ पर — हर बदलाव खींचते समय सुनाई देता है और ख़त्म होने पर पूर्ववत का एक चरण बनता है।","changelog.2bcc3000b0a9":"<strong>ऑटोमेशन लेन</strong> — हर पार्ट पर वॉल्यूम, पैन, चौड़ाई, लो- और हाई-पास कटऑफ़, रेज़ोनेंस, रीवर्ब और डिले सेंड, ड्राइव, क्रश, गेट की गहराई और पिच के लिए, और मास्टर वॉल्यूम व लो-पास के लिए — ड्रॉ की जाती हैं, मोड़ी जाती हैं, चुनी और खिसकाई जाती हैं; आकार के स्टैम्प (रैंप, S-कर्व, साइन, त्रिकोण, वर्ग, आरी, रैंडम स्टेप) और किसी रेंज का कॉपी/पेस्ट; किसी मूव का अपना स्वीप या डाइव उसी लेन पर संपादित होता है जिस पर वह बजता है। हर सैंपल पर पढ़ी जाती हैं, लाइव में भी और प्रिंट में भी।","changelog.7d436c4c3696":"<strong>सेक्शन।</strong> जोड़ें, हटाएँ, क्रम बदलने के लिए खींचें (सेक्शन की हर चीज़ उसके साथ जाती है), लंबाई बदलें, प्रकार बदलें (नए प्रकार के लिए उसकी गतिविधि फिर से बनाई जाती है), नाम बदलें और लॉक करें — सेक्शन के मेनू से या उसके हेडर से।","changelog.48c0b2ee5ed9":"<strong>लॉक करें और फिर से बनाएँ।</strong> लॉक किया गया सेक्शन या संपादित क्लिप फिर से बनाने पर कभी नहीं छुई जाती, और फिर से बनाना किसी पड़ोसी को कभी नहीं खिसकाता; <em>क्या बदला</em> हर उस पार्ट और मूव की सूची दिखाता है जो बदला, सेक्शन-दर-सेक्शन।","changelog.e101a7e88895":"<strong>हाथ से मूव्स।</strong> हर मूव की एक पैलेट (मॉडल के अपने मूव सबसे पहले), जिन्हें मार्कर स्ट्रिप पर रखा, खींचा, फैलाया और हटाया जाता है; मूव इंस्पेक्टर उसके पैरामीटर और पार्ट संपादित करता है और प्रीव्यू के दौरान उसे सुनाता है — ठीक उसी तरह बनाया गया जैसे प्लानर कोई मूव बनाता है।","changelog.48cc96242f52":"सॉन्ग अरेंजमेंट व्यू के हर बदलाव का <strong>असीमित पूर्ववत और फिर से करना</strong>, जिसे इंस्टेंस सँभालता है और जो प्रोजेक्ट के साथ सेव होता है — हेडर के “पूर्ववत करें” और “फिर से करें” से (दोनों अपने चरण का नाम बताते हैं) या <code>Ctrl/Cmd+Z</code>, <code>Ctrl/Cmd+Shift+Z</code>, <code>Ctrl+Y</code> से। <strong>क्रैश से सुरक्षित:</strong> हर बदलाव उसी पल आपके ऐप-डेटा फ़ोल्डर में लिख दिया जाता है (आपके होस्ट के अपने थ्रेड से अलग), और सेव करने से पहले बंद हुआ होस्ट आपके आख़िरी बदलाव के साथ फिर से खुलता है, और यह बताता है — साथ में <em>सहेजा गया संस्करण रखें</em>, उस स्थिति के लिए जब बदलाव किसी दूसरी कॉपी का था (<em>Save As</em> के बाद फिर से खोला गया कोई पुराना प्रोजेक्ट)। डुप्लिकेट किया गया ट्रैक अपना अलग ऑटोसेव रखता है।","changelog.4a2ef5527abc":"<strong>होस्ट में बदला गया लूप अरेंजमेंट को फिर से फ़िट करता है।</strong> नई लूप लंबाई या टाइम सिग्नेचर आपके संपादनों को खोने देने के बजाय उन्हें वैसे ही उस पर बिछा देता है जैसे आयात करता है; पूर्ववत वहीं से फिर शुरू होता है।","changelog.7e8282605542":"<strong>ग्रिड और साफ़-सफ़ाई।</strong> बार, बीट, 1/8, 1/16, उनके ट्रिपलेट पर स्नैप, या बंद; मिनीमैप के साथ ज़ूम; 4/8/16-बार फ़्रेज़ की शेडिंग; जहाँ क्लिप मिलती हैं वहाँ 3 ms के ऑटो-क्रॉसफ़ेड; और स्नैप बंद होने पर किनारा लूप के सबसे नज़दीकी ज़ीरो क्रॉसिंग पर खिसका दिया जाता है (1 ms के भीतर)। संपादनों का कोई भी क्रम क्लिक पैदा नहीं करता।","changelog.9ed31073c953":"<strong>अरेंजमेंट शेल्फ़।</strong> एक लूप, कई नाम वाले अरेंजमेंट, हेडर के अरेंजमेंट मेनू से: <em>नया अरेंजमेंट</em>, <em>प्रतिलिपि बनाएँ</em>, <em>नाम बदलें</em>, <em>हटाएँ</em> (पूर्ववत किया जा सकता है), <em>स्विच करें</em> — बजते समय अगली बार लाइन पर, रुके होने पर तुरंत — और <em>तुलना करें</em>, किन्हीं दो के बीच A/B टॉगल; हर एक के अंदर चार स्नैपशॉट (A–D)। स्विच करने पर लूप कभी फिर से कैप्चर या डिकोड नहीं होता, और जिस अरेंजमेंट से हटकर आप वापस आते हैं, वह ठीक वैसा ही रहता है जैसा था। शेल्फ़ का हर काम पूर्ववत का एक चरण है, और <code>.unloop</code> फ़ाइल पूरी शेल्फ़ साथ रखती है।","changelog.04b5ecf4f4ca":"<strong><code>.unarr</code> अरेंजमेंट फ़ाइलें।</strong> <em>अरेंजमेंट निर्यात करें…</em> एक अरेंजमेंट को उसके लूप के बिना लिखता है; <em>अरेंजमेंट आयात करें…</em> उसे आपके खुले लूप पर बिछाता है — उसके सेक्शन, क्लिप, मूव्स और लेन उनकी पहचान से ढूँढ़े जाते हैं (दूसरा हुक, वर्स के ड्रम), सेक्शन पूरे लूप में बिछाए जाते हैं और नए लूप की लंबाई के हिसाब से छोटे-बड़े किए जाते हैं — और जिस चीज़ को जगह नहीं मिली उसकी सूची दिखाता है।","changelog.900ccf7596b0":"<strong>कीबोर्ड पहले।</strong> शॉर्टकट की एक ही तालिका ऐप को चलाती है और सूची भी लिखती है — Unloop में <code>?</code> दबाएँ, या डॉक्स साइट देखें। टाइमलाइन का हर संपादन बिना माउस के होता है: क्लिपों में एक-एक करके चलें, उन्हें स्नैप के हिसाब से खिसकाएँ, उनका आकार बदलें, उनका गेन बदलें, उनके फ़ेड हैंडल पकड़ें, विभाजित करें, उलटें, लॉक करें, और उनके मेनू खोलें। टाइमलाइन की कुंजियाँ तब काम करती हैं जब फ़ोकस मैप पर हो (या कहीं न हो), फ़ोकस वाले किसी बटन, लेन या डायलॉग पर कभी नहीं। स्क्रीन रीडर के लिए मैप का नाम और विवरण दिया गया है, क्लिप-दर-क्लिप और हैंडल-दर-हैंडल।","changelog.7757cf2e3226":"<strong>प्रोजेक्ट स्टेट अब स्कीमा 6 है, और <code>.unloop</code> दस्तावेज़ स्कीमा 2</strong>: संपादन, इतिहास, शेल्फ़, और हर अरेंजमेंट के संपादन व स्नैपशॉट। पुराने प्रोजेक्ट और फ़ाइलें वैसे ही खुलते हैं जैसे वे थे।","changelog.852a0be917e2":"<strong>साझा Freally क्रेट <code>shared-v5</code> पर आ गए हैं</strong> — MIDI Master का <code>shared-v3</code> से <code>shared-v5</code>, और उसका nih-plug फ़ोर्क <code>df472391</code> पर: विंडो खिसकाने पर एडिटर का पेज अपनी विंडो के ठीक नीचे टिका रहता है (WebView2 को बताया जाता है कि विंडो खिसकी है और उसे वापस उसके नीचे रखा जाता है), <code>freally-extract</code> और nih-plug का <code>process_mode()</code> उपलब्ध हैं, और रोस्टर स्नैपशॉट नए टैग पर फिर से लिया गया है (उसका डेटा नहीं बदला)।","changelog.fb1d01817381":"<strong>रिपॉज़िटरी सार्वजनिक है</strong> — <code>MikesRuthless12/freally-unloop</code>, सर्वाधिकार सुरक्षित; साझा क्रेट सार्वजनिक <code>MikesRuthless12/freally-midi-master</code> से आते हैं, और macOS रिलीज़ बिल्ड को किसी सीक्रेट की ज़रूरत नहीं।","changelog.01c79b299c9b":"<strong>कंटीन्यूअस इंटीग्रेशन GitHub पर चलता है</strong>, Windows, Linux और macOS पर, हर पुश और पुल रिक्वेस्ट के लिए — हर गेट, clap-validator और strictness 10 पर pluginval, हर रनर पर (macOS पर AU)। अब किसी कमिट में <code>[skip ci]</code> नहीं होता।","changelog.8c8f3f1edad1":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-09-28\">2026-09-28</time></span><span class=\"release__title\">C: कैप्चर, प्रीव्यू और प्रिंट</span>","changelog.3ccc718cc694":"MVP पूरा हो गया है। हर इंस्टेंस अपने लूप का एक चक्र कैप्चर करता है और ट्रैक को मेमोरी से बजाता है; आपका DAW रुका हो तब पूरे अरेंजमेंट का प्रीव्यू Unloop के अंदर चलता है; <strong>प्रिंट</strong> इसे रेंडर करता है — मिक्स, स्टेम्स, एक पार्ट या एक सेक्शन — WAV, AIFF, FLAC या MP3 के रूप में, सैंपल-दर-सैंपल वही जो आपने लाइव सुना; ड्रैग रैक इसे सीधे आपके ट्रैकों पर डाल देता है; हर फ़ाइल के साथ एक रसीद जाती है; और लूप एक <code>.unloop</code> प्रोजेक्ट के रूप में सेव होता है, जिसे आप फिर से खोल सकते हैं, या अपने बाकी लूप के साथ लूप लाइब्रेरी में फिर से ढूँढ़ सकते हैं।","changelog.b88c7903914f":"<strong>कैप्चर।</strong> <em>जनरेट करें</em> के बाद हर इंस्टेंस अपने लूप का ठीक एक चक्र रिकॉर्ड करता है — अगली लूप सीमा से <code>loop_bars</code> जितना संगीत, 44.1, 48 और 96 kHz पर सैंपल तक सटीक — सीधे आपके DAW के इनपुट से, कभी Unloop के अपने आउटपुट से नहीं। प्रीव्यू बटनों के पास की <strong>लाइव / कैप्चर किया</strong> चिप बताती है कि स्थिति क्या है (इंतज़ार, कैप्चर हो रहा, कैप्चर हुआ, पुराना), साथ में <em>फिर से कैप्चर करें</em> और <em>कैप्चर भूल जाएँ</em>। टेक के बीच में रुकना, किसी और जगह जाना या टेम्पो बदलना अधूरे टेक को फेंक देता है और अगली बार चलाने पर फिर कोशिश करता है; 64 सेकंड से लंबा लूप साफ़ शब्दों में अस्वीकार किया जाता है। कैप्चर उनकी सामग्री (BLAKE3) के आधार पर आपके ऐप-डेटा फ़ोल्डर में रखे जाते हैं, 2 GB तक, और सबसे कम हाल में इस्तेमाल हुए सबसे पहले हटते हैं; होस्ट प्रोजेक्ट सिर्फ़ हैश सेव करता है, और जिस प्रोजेक्ट का कैप्चर मिट गया हो, वह आपसे लूप एक बार चलाने को कहता है।","changelog.b3429b1f4985":"<strong>लूप बदल गया — फिर से कैप्चर करें?</strong> जब आ रहा लूप लगातार दो चक्रों तक वह नहीं होता जो कैप्चर हुआ था (बैंड-दर-बैंड तुलना करके), तो चिप यह बताती है। बजते समय कभी कुछ नहीं बदला जाता; फिर से कैप्चर तभी होता है जब आप दबाते हैं।","changelog.09d9a80b48ef":"<strong>मेमोरी से बजाया गया।</strong> कैप्चर होने के बाद इंस्टेंस ट्रैक को अपने कैप्चर से बजाता है, होस्ट की पोज़िशन से बँधा हुआ — ऐसे लूप पर भी कोई ड्रिफ़्ट नहीं जिसका चक्र सैंपल की पूर्ण संख्या न हो, स्रोत बदलने पर एक क्रॉसफ़ेड, और फिर भी ज़ीरो अतिरिक्त लेटेंसी। मेमोरी वाले मूव्स कैप्चर को पढ़ते हैं; कैप्चर होने से पहले वे लूप के हाल के हिस्से को पढ़ते हैं, और मैप यह बताता है।","changelog.2d3fbd1189a2":"<strong>Unloop के अंदर प्रीव्यू।</strong> होस्ट रुका हो तो मास्टर सेक्शन के प्ले, पॉज़, स्टॉप और लूप बटन (या स्पेस बार) पूरा ट्रैक Unloop में बजाते हैं — चैनल के सभी इंस्टेंस एक साथ, हर एक अपने कैप्चर से, एक DAW के अंदर ठीक एक ही सैंपल पर और अलग-अलग प्रोसेस के बीच एक ब्लॉक के भीतर। किसी जगह जाने के लिए मैप के रूलर पर क्लिक करें; किसी सेक्शन को लूप करें। होस्ट में प्ले दबाएँ और वह तुरंत कमान सँभाल लेता है — प्रीव्यू वहीं रुकता है जहाँ ऑडियो था और यह बताता है। जिन पार्ट को आपका होस्ट रुके होने पर नहीं चलाता (Logic के नॉन-लाइव ट्रैक) और जिन पार्ट का अभी कुछ भी कैप्चर नहीं हुआ, उनके नाम बताए जाते हैं।","changelog.5f7f65713c74":"<strong>मूव्स II</strong>: रिवर्स, हाफ़-टाइम (टेप और स्ट्रेच), गेट, लो-फ़ाई, रिवर्ब थ्रो (Unloop का अपना रिवर्ब), डिले थ्रो (डॉटेड एट्थ, पिंग-पॉन्ग), पिच डाइव और रिवाइंड — हर एक के अपने टाइमिंग, क्लिक और CPU टेस्ट के साथ। हाफ़-टाइम सेक्शन अब बजाए जाते हैं (कैप्चर से; जब तक कैप्चर न हो, पूरी रफ़्तार पर)। एक साथ चार मूव्स — उनमें कोई भी नया मूव शामिल हो — पूरे ऑडियो कोर पर 48 kHz पर 128-सैंपल ब्लॉक में ≈25–27 µs का ख़र्च डालते हैं: एक कोर का लगभग 1 %, 1.5 % के बजट के भीतर।","changelog.aae38e7e09b4":"<strong>प्रिंट।</strong> ट्रैक कैप्चर से ऑफ़लाइन रेंडर होता है, उसी कोड से जो उसे लाइव बजाता है — हर पार्ट का एक स्टेम, प्री-फ़ेडर और बार 1 से पूरी लंबाई का, ताकि कोई भी DAW उन्हें सही जगह पर बिठा सके, और मिक्स उनका योग। हर नए मूव और हाफ़-टाइम क्लिप के लिए टेस्ट लाइव प्लेबैक और प्रिंट को बराबर रखता है — प्रिंट के अपने ब्लॉक में बिट-दर-बिट, और मेमोरी वाले मूव्स होस्ट के बाकी ब्लॉक आकारों में −100 dB के भीतर; दो बार प्रिंट करने पर वही बाइट्स मिलते हैं। तीन मिनट, आठ स्टेम का प्रिंट लगभग 3 सेकंड लेता है, हर फ़ाइल के लिए प्रोग्रेस बार और <strong>रद्द करें</strong> के साथ, जो कुछ भी पीछे नहीं छोड़ता।","changelog.30dab5974741":"<strong>WAV, AIFF, FLAC और MP3।</strong> WAV 16/24-बिट या 32-बिट फ़्लोट, हर डेप्थ पर <code>acid</code> चंक के साथ, ताकि Ableton, FL और Acid इसे आपके टेम्पो पर वार्प करें; AIFF 16/24 (इसमें टेम्पो रखने की कोई जगह नहीं, और डायलॉग यह बताता है); FLAC 16/24, <code>BPM</code> टैग के साथ; MP3 128–320 kbps, <code>TBPM</code> टैग के साथ (और एक नोट कि MP3 एनकोडर डिले जोड़ता है — जिन स्टेम्स को सटीक मिलना है, उनके लिए WAV या FLAC इस्तेमाल करें)। सैंपल रेट जैसा कैप्चर हुआ, या 44.1/48/88.2/96 kHz (MP3 अधिकतम 48), जो हेडर में लिखे जाने से पहले ही कन्वर्ट किया जाता है; बिट डेप्थ घटने पर सीड वाला TPDF डिदर, हर प्रिंट पर एक जैसा। अपने टेस्ट में हर फ़ॉर्मैट को Unloop के अपने डिकोडर से वापस पढ़ा जाता है।","changelog.3cff712e7690":"<strong>प्रिंट मीटर और एक सेफ़्टी लिमिटर।</strong> मिक्स का पीक (dBFS), 4× ओवरसैंपल किया हुआ ट्रू पीक (dBTP) और इंटीग्रेटेड लाउडनेस (LUFS, ITU-R BS.1770-4), जो एक्सपोर्ट पूरा होने पर दिखते हैं; सिर्फ़ मिक्स पर एक वैकल्पिक −1 dBTP लिमिटर, जो बताता है कि उसने मिक्स को कितना नीचे खींचा।","changelog.f311d0c466d8":"<strong>एक्सपोर्ट डायलॉग</strong> (मास्टर सेक्शन में <strong>प्रिंट</strong>): क्या — मिक्स, स्टेम्स, कोई भी पार्ट, एक सेक्शन या पूरा ट्रैक — फ़ॉर्मैट, क्वालिटी, रेट, डिदर, लिमिटर और रसीदें, और वे फ़ाइल नाम जो यह लिखेगा, जिन्हें फ़ाइलों का नाम रखने वाला कोड आपके टेम्पलेट से लाइव सूचीबद्ध करता है। डिफ़ॉल्ट टेम्पलेट <code>{genre} - {mode} - {what} - {bpm} BPM - {key}</code> है; अगर आप नाम उसमें चाहते हैं तो <code>{model}</code> मौजूद है। <strong>कोई भी डिफ़ॉल्ट फ़ाइल नाम कभी किसी कलाकार या प्रोड्यूसर का नाम नहीं रखता</strong> — एक टेस्ट रोस्टर के हर नाम, हर मोड और हर एक्सपोर्ट से गुज़रकर इसे पक्का करता है।","changelog.361d5bae41fd":"<strong>ड्रैग रैक।</strong> मिक्स, स्टेम्स, एक पार्ट या एक सेक्शन अपने ट्रैकों पर ड्रैग करें (डिफ़ॉल्ट रूप से WAV 24-बिट); ड्रैग शुरू होने से पहले फ़ाइलें रेंडर हो जाती हैं, इसलिए ड्रॉप पूरा का पूरा पहुँचता है।","changelog.8552eba608bc":"<strong>रसीदें, डिफ़ॉल्ट रूप से चालू।</strong> हर एक्सपोर्ट और हर ड्रैग के साथ <code>&lt;name&gt;.unloop-receipt.json</code>: Unloop और डेटासेट के संस्करण, Freally MIDI Master टैग, मॉडल, मोड और सीड, प्लान हैश, हर पार्ट का कैप्चर हैश, फ़ाइलें और क्या माँगा गया था — वही ट्रैक दोबारा बनाने के लिए काफ़ी। इन्हें बंद करना एक प्राथमिकता है, कभी डिफ़ॉल्ट नहीं।","changelog.385eadae4891":"<strong>लूप प्रोजेक्ट (<code>.unloop</code>)।</strong> हेडर की शुरुआत में फ़ोल्डर बटन से <em>लूप प्रोजेक्ट सेव करें…</em> और <em>लूप प्रोजेक्ट खोलें…</em>: लूप एक बार रखा जाता है (उसके पार्ट 24-बिट FLAC के रूप में) और उस पर अरेंजमेंट। एक ही प्रोजेक्ट को दो बार सेव करने पर वही बाइट्स मिलते हैं; उसे खोलने पर वही प्लान मिलता है, हैश तक, और बिना पूरा बजाए वही कैप्चर। Unloop के नए संस्करण से बना प्रोजेक्ट पूरी तरह अस्वीकार कर दिया जाता है (“नए Unloop से बना — खोलने के लिए अपडेट करें”); कोई पार्ट ग़ायब या ख़राब हो तो बाकी खुल जाता है और उस पार्ट का नाम बताता है जिसे फिर से देना है। सेव करने से कोई फ़ाइल कभी ओवरराइट नहीं होती — लिए हुए नाम के साथ <code> (2)</code> जुड़ जाता है — और किसी प्रोजेक्ट को दोबारा सेव करने पर उसमें वह सब बना रहता है जो इस इंस्टेंस ने नहीं बनाया।","changelog.a86b818719c2":"<strong>लूप लाइब्रेरी।</strong> अपने लूप फ़ोल्डर जोड़ें: उनमें मौजूद हर <code>.unloop</code> और हर WAV, AIFF, FLAC, MP3 और MIDI फ़ाइल की सूची बनती है, उसके बार, BPM (<em>फ़ाइल से</em> — उसका <code>acid</code> चंक, टैग या नाम — जब तक <code>v0.7.0</code> में पहचान नहीं आती), टैग, कितनी बार अरेंज हुई, आख़िरी संपादन और एक छोटी वेवफ़ॉर्म के साथ। BPM, स्केल, टैग या <em>कभी अरेंज नहीं हुआ</em> से खोजें और फ़िल्टर करें; किसी पंक्ति को सुनने के लिए उस पर क्लिक करें (<code>↑/↓</code> सूची में चलते हैं, <code>Esc</code> रोकता है) — सिर्फ़ Unloop के अंदर, आपके DAW का ट्रांसपोर्ट कभी हिलाए बिना — और जब वह ठीक एक लूप हो, तो उसे <strong>अरेंज करें</strong>। दो हज़ार फ़ाइलें एक-दो सेकंड में इंडेक्स हो जाती हैं, होस्ट के थ्रेड से अलग। यह आपके फ़ोल्डरों को सिर्फ़ पढ़ती है। MIDI लूप अभी सूची में दिखते हैं और <code>v0.7.0</code> में अरेंज किए जा सकेंगे।","changelog.a26b2595dfc9":"<strong>हाल के प्रोजेक्ट</strong>, सबसे नया सबसे पहले, फिर से खोलने के लिए एक क्लिक; जो प्रोजेक्ट कहीं और चला गया हो, वह <em>सूची से हटाएँ</em> के साथ “नहीं मिला” के रूप में दिखता है (पंक्ति हटती है, फ़ाइल कभी नहीं)।","changelog.2e4a3278fa31":"<strong>लूप कटर</strong> — <em>लंबी फ़ाइल से लूप बनाएँ…</em>: किसी टेम्पो पर शुरुआती बार और लंबाई (1, 2, 4, 8 या 16 बार) चुनें, कटे हुए हिस्से को बार-बार दोहराते हुए सुनें, फिर उसे एक नए लूप प्रोजेक्ट के रूप में <em>अरेंज करें</em>। कट सैंपल तक सटीक होता है, और मूल फ़ाइल कभी नहीं बदलती।","changelog.22f2979096ba":"<strong>बस पैनल</strong> दिखाता है कि किन इंस्टेंस के पास कैप्चर है, और प्रीव्यू चलते समय किन्हें उनका होस्ट नहीं चला रहा।","changelog.d0c12bfcdf93":"<strong>हर प्लान हैश बदला — प्लान नहीं।</strong> प्लान उस Freally MIDI Master टैग का नाम बताता है जिस पर उसका डेटा आयात हुआ था (<code>mm-shared-v2/…</code>, पहले <code>mm-shared-v1/…</code>); डेटा नहीं बदला, इसलिए हर नाम, मोड और सीड ठीक पहले की तरह अरेंज करता है। 24 गोल्डन प्लान सिर्फ़ अपनी हेडर लाइन में बदले।","changelog.81dd6b6d682d":"<strong>साझा Freally क्रेट <code>shared-v2</code> पर आ गए हैं</strong> — MIDI Master का <code>freally-encode</code> (हर एक्सपोर्ट की गई फ़ाइल का हर बाइट) और <code>freally-drag</code> (Windows, macOS और Linux पर नेटिव ड्रैग), जिन्हें Unloop के लिए MIDI Master से अलग निकाला गया, उसी टैग पर इंजन और वेबव्यू अडैप्टर के साथ। इंजन अब अपने-आप बिल्ड होता है, इसलिए Linux CI का फ़ुल-चेकआउट वाला जुगाड़ हट गया है।","changelog.25e088b374a9":"<strong>हर आउटपुट के लिए एक ही परफ़ॉर्मर।</strong> शेड्यूल और परफ़ॉर्मर अपने अलग क्रेट <code>performance</code> में चले गए हैं, जिससे होकर लाइव प्लेबैक, प्रीव्यू और प्रिंट सब बजते हैं; <code>render</code> में प्रिंट, एनकोडरों का मुख्य द्वार, डिकोडर, मीटर, लिमिटर और <code>.unloop</code> कंटेनर हैं।","changelog.759e88328427":"<strong>बस फ़ाइल का लेआउट 2 पर आ गया है</strong> (<code>&lt;letter&gt;.v2.mmap</code>), जिसमें हर इंस्टेंस का कैप्चर हैश और चैनल की प्रीव्यू घड़ी होती है। Unloop <code>v0.4.0</code> और यह संस्करण अलग-अलग प्रोसेस के बीच कभी कोई चैनल साझा नहीं करते — हर कॉपी एक साथ अपडेट करें। <code>v0.4.0</code> से सेव किया गया होस्ट प्रोजेक्ट यहाँ खुलता है (उसकी स्टेट स्कीमा 4 पर आ जाती है, जो कैप्चर का संदर्भ देती है); यहाँ सेव किए गए प्रोजेक्ट को <code>v0.4.0</code> पूरी तरह अस्वीकार कर देता है।","changelog.2d5e534dd29f":"<strong>लेवल के बदलाव 2 ms में धीरे-धीरे होते हैं</strong> (पहले 5 ms), इसलिए तेज़ गेट के किनारे अपना आकार बनाए रखते हैं; हर किनारा अब भी −60 dB क्लिक टेस्ट पास करता है।","changelog.ddd7a1094504":"<strong>खोज Ø, ß और Ł जैसे अक्षरों को सामान्य अक्षरों से मिलाती है</strong>, इसलिए “mo” लिखने पर MØ मिल जाता है।","changelog.f6ed90cd965e":"<strong>कंसोल के मास्टर सेक्शन</strong> में प्रीव्यू बटन, सोर्स चिप, <strong>प्रिंट</strong> और ड्रैग रैक जुड़ गए हैं; प्रीव्यू चलते समय टेप काउंटर <em>प्रीव्यू चल रहा है</em> दिखाता है; हेडर लूप प्रोजेक्ट के फ़ोल्डर बटन से शुरू होता है।","changelog.044bd3e3ee09":"<code>THIRD-PARTY-NOTICES.md</code> में अब 437 कंपोनेंट हैं (पहले 381): इनमें डिकोडर (Symphonia, MPL-2.0 — एक डिकोडर, जिसकी लाइसेंस नीति अनुमति देती है), FLAC और MP3 एनकोडर, रीसैंपलर और नेटिव फ़ाइल डायलॉग शामिल हैं।","changelog.1246fc93bca0":"ठीक किया गया","changelog.cbcb91b5782e":"<strong>Unloop का एडिटर अपनी अलग ब्राउज़र प्रोफ़ाइल रखता है</strong> (<code>%APPDATA%\\Freally Unloop\\webview</code>, और macOS व Linux पर उसके समकक्ष), अब Freally MIDI Master वाला फ़ोल्डर नहीं: दोनों साथ-साथ चलने पर एक एडिटर ख़ाली रह सकता था (“The requested resource is in use”)।","changelog.250423c9e9f8":"इस चरण की कोड और सुरक्षा समीक्षा से:","changelog.075cc32b4202":"<strong>हर फ़ाइल को शत्रुतापूर्ण मानकर पढ़ा जाता है</strong> — एक <code>.unloop</code>, लाइब्रेरी का कोई लूप, कैश किया गया कैप्चर, कोई प्राथमिकता: पढ़ने से पहले आकार की सीमा तय होती है, उससे कुछ भी आवंटित करने से पहले हर लंबाई को मौजूद बाइट्स से मिलाकर जाँचा जाता है, और अंदाज़ा लगाने के बजाय अस्वीकार किया जाता है। डिकोडर और प्रोजेक्ट रीडर किसी फ़ाइल पर कभी पैनिक नहीं करते (रैंडम बाइट्स और झूठी लंबाई वाले टेस्ट इसे पक्का करते हैं), और प्रोजेक्ट के पार्ट एक-एक करके डिकोड होते हैं, सिर्फ़ तब जब कोई इस्तेमाल हो, इसलिए एक छोटी शत्रुतापूर्ण फ़ाइल होस्ट से गीगाबाइट्स नहीं भरवा सकती।","changelog.e574701848b3":"<strong>कुछ भी नेटवर्क को नहीं छूता।</strong> नेटवर्क शेयर (<code>\\\\server\\share</code>) या डिवाइस पाथ को कुछ भी छूने से पहले ही अस्वीकार कर दिया जाता है; मैप की गई नेटवर्क ड्राइव पर रखा प्रोजेक्ट, लूप, लूप का फ़ोल्डर या एक्सपोर्ट फ़ोल्डर, उस पर कोई भी फ़ाइल खोलने या देखने तक से पहले अस्वीकार कर दिया जाता है (देखना भी एक कनेक्शन है); और जो एक्सपोर्ट फ़ोल्डर किसी शेयर तक पहुँचता हो — उसमें जाने वाला कोई लिंक या जंक्शन — कुछ भी लिखे जाने से पहले अस्वीकार कर दिया जाता है।","changelog.24ed701d1a3d":"<strong>न कुछ ओवरराइट होता है, न कुछ आधा-लिखा छूटता है।</strong> लिए हुए फ़ाइल नाम के साथ <code> (2)</code> जुड़ जाता है; फ़ाइलें बगल में लिखी जाती हैं और फिर अपनी जगह पर ले जाई जाती हैं, और विफल या रद्द हुआ एक्सपोर्ट जो लिखा था उसे वापस ले लेता है। फ़ाइल नाम हर सिस्टम पर सादे नाम होते हैं (न डिवाइस नाम, न सेपरेटर)।","changelog.d189c3bc173c":"<strong>जो होस्ट Unloop को तब अनलोड करता है जब उसका कोई थ्रेड अभी चल रहा हो</strong> — खुला फ़ाइल डायलॉग, फ़ोल्डर चुनने में अटका कोई एक्सपोर्ट — वह Windows पर क्रैश नहीं होता: ऐसा हर थ्रेड अपने आख़िरी निर्देश तक प्लगइन को थामे रखता है।","changelog.a3c71b90162b":"ज्ञात सीमाएँ","changelog.c8a83adf7aa9":"<code>v0.5.0</code> की होस्ट जाँचें — FL Studio, Ableton Live और Reaper में कैप्चर, प्रीव्यू, प्रिंट, फ़ॉर्मैट और ड्रैग-आउट — लिखी जा चुकी हैं (<code>Live-To-Do.md</code> § 4) पर अभी हाथ से की नहीं गईं; macOS और Linux पर ड्रैग-आउट लिखा जा चुका है, पर अभी किसी असली DAW में ड्रॉप नहीं किया गया।","changelog.fff6674de28f":"ड्रैग करते समय अभी उस चीज़ की कोई तस्वीर नहीं दिखती जिसे आप ड्रैग कर रहे हैं।","changelog.342624d6fcd1":"आख़िरी बार पर रिवर्ब या डिले थ्रो ट्रैक की आख़िरी बार लाइन पर कट जाता है; प्रिंट उसके आगे गूँजता नहीं रहता।","changelog.b11de52e56ae":"कंसोल के फ़ेडर आने तक (<code>v0.6.0</code>) मिक्स में पार्ट फ़ेडर यूनिटी पर रहते हैं; शेल्फ़ आने तक एक लूप प्रोजेक्ट में एक ही अरेंजमेंट रहता है।","changelog.7b2349c31bb6":"पहचान आने तक (<code>v0.7.0</code>) लूप का स्केल पता नहीं होता, इसलिए तब तक डिफ़ॉल्ट फ़ाइल नामों में <code>{key}</code> शामिल नहीं होता।","changelog.2abf238bf14a":"अलग डिस्प्ले स्केल वाले दूसरे मॉनिटर पर, एडिटर अपना आकार मुख्य डिस्प्ले के हिसाब से तय करता है।","changelog.f56d1c79ff84":"macOS पर डायलॉग या एक्सपोर्ट चलते समय अभी कुछ भी प्लगइन को थामे नहीं रखता (<code>SECURITY.md</code>, <em>ज्ञात सीमाएँ</em>)।","changelog.13da7fa23214":"<code>v0.5.0</code> सिर्फ़ Windows और Linux के लिए जारी हुआ है; इसके लिए कोई macOS बिल्ड (AU, CLAP, VST3 या स्टैंडअलोन) नहीं बनाया गया।","changelog.adb870b6c393":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-09-26\">2026-09-26</time></span><span class=\"release__title\">R: भूमिकाएँ और कंडक्टर</span>","changelog.277edf17b8c6":"हर पार्ट के ट्रैक पर Unloop लगाएँ और वे सब मिलकर एक ही ट्रैक बजाते हैं। पहला इंस्टेंस संचालन करता है; बाकी हर इंस्टेंस सैंपल तक सटीक उसके प्लान का पालन करता है और सिर्फ़ अपने पार्ट के मूव्स बजाता है — ड्रम बस पर ड्रम ड्रॉप-आउट होते हैं, बेस ट्रैक पर बेस — और कंसोल हर इंस्टेंस के लिए एक स्ट्रिप दिखाता है। साथ ही एडिटर का डिज़ाइन भी नया किया गया।","changelog.d40fc08c53e8":"<strong>भूमिकाएँ।</strong> हर इंस्टेंस एक भूमिका लेता है — पूरा लूप, ड्रम (या किट का एक हिस्सा), बेस, मेलोडी, काउंटर-मेलोडी, कॉर्ड्स, वोकल, FX या प्रोड्यूसर टैग — अपनी स्ट्रिप से या “भूमिकाएँ और बस” पैनल से, और किसी भी विंडो से दूसरे इंस्टेंस की भूमिका भी। एक ही तरह के दो इंस्टेंस पर नंबर लगते हैं (“मेलोडी 2”) और वे एक लेन साझा करते हैं। प्लान जिस भूमिका के लिए कोई पार्ट लिखता है पर जिसे किसी ने नहीं लिया, वह मैप पर “कहीं नहीं बजाया गया” के रूप में चिह्नित होता है।","changelog.bfed3623cf95":"<strong>कंडक्टर।</strong> किसी चैनल का पहला इंस्टेंस संचालन करता है: वह प्लान बनाता है, और बाकी हर इंस्टेंस उसके इनपुट और हैश पाता है — ऑडियो कभी नहीं — वही प्लान फिर से बनाता है और वापस रिपोर्ट करता है। किसी भी विंडो में बदला गया प्लान कंडक्टर को भेजा जाता है और सब तक पहुँचता है। जब कंडक्टर चला जाता है, तो अगला इंस्टेंस एक सेकंड के भीतर बैटन सँभाल लेता है और ट्रैक को आगे बढ़ाता है।","changelog.d186a7625d16":"<strong>सैंपल तक संरेखित।</strong> हर इंस्टेंस हर मूव का किनारा ठीक एक ही सैंपल पर रखता है, चाहे उसका ट्रैक किसी भी ब्लॉक आकार पर चले; ड्रम बस पर बजाया गया किट मूव उस बस के बैंड्स में वैसे ही बँटता है जैसे एक इंस्टेंस वाला ट्रैक उसे बजाता।","changelog.0d92b38aa91d":"<strong>बस लैंप और “भूमिकाएँ और बस” पैनल।</strong> हरा: इंस्टेंस इस DAW की मेमोरी साझा करते हैं। पीला: होस्ट हर प्लगइन को उसके अपने प्रोसेस में रखता है (Bitwig का सैंडबॉक्स, Reaper की ब्रिजिंग, FL की ब्रिजिंग, macOS का AU होस्ट), और इंस्टेंस इसके बजाय एक छोटी फ़ाइल के ज़रिए मिलते हैं जिसे सिर्फ़ मालिक पढ़ सकता है — यह बताया जाता है, छिपाया नहीं जाता। लाल: कोई इंस्टेंस कंडक्टर का प्लान नहीं बजा रहा, साथ में <strong>प्लान फिर से भेजें</strong>। चार चैनल, A–D, एक DAW में दो प्रोजेक्ट को अलग रखते हैं; जो चैनल पहले से किसी दूसरे प्रोजेक्ट का प्लान बजा रहा हो, वह यह बताता है और अगला चैनल या उसी का पालन करने का विकल्प देता है।","changelog.c4f20b079ad4":"<strong>कंसोल v2</strong>: हर इंस्टेंस की एक स्ट्रिप, भूमिका के क्रम में, अपने लैंप, फ़िल्टर नॉब, VU और फ़ेडर के साथ, जो ठीक वही दिखाते हैं जो उस इंस्टेंस के ऑडियो थ्रेड ने लागू किया; इस इंस्टेंस की स्ट्रिप पर रूपरेखा, और कंडक्टर का बैटन जलता हुआ।","changelog.ad55bbaf935b":"<strong>नया रूप।</strong> ज़्यादा गहरा, ज़्यादा शांत एडिटर: हेडर के हर कंट्रोल की एक ही ऊँचाई, किनारा और भराव, आइकन वाला सर्च फ़ील्ड, नए सिरे से बनाया गया मोड पिकर, घड़ी का बैज रूपरेखा के बजाय हल्के रंग से भरा, ख़ाली मैप एक टाइमलाइन की परछाईं की तरह बना, और तीन मॉड्यूल वाला कंसोल — बस, नाम-पट्टियों वाली स्ट्रिप्स का एक धँसा हुआ रैक, और पूरी चौड़ाई वाले “जनरेट करें” बटन के साथ मास्टर सेक्शन।","changelog.c624ea467282":"<strong>डिफ़ॉल्ट रूप से गहरा।</strong> ऑपरेटिंग सिस्टम की सेटिंग चाहे जो हो, एडिटर गहरी थीम में खुलता है; <em>सिस्टम</em> और <em>हल्का</em> अब भी सेटिंग्स में हैं, और आपकी चुनी थीम याद रखी जाती है।","changelog.14fe50ad6168":"<strong>हर भाषा में सब कुछ फ़िट होता है।</strong> कोई लेबल अपने बॉक्स से बाहर नहीं निकलता — लंबा भूमिका नाम अपनी पट्टी पर अगली पंक्ति में चला जाता है, मैप पर लंबा सेक्शन नाम दबाने के बजाय एलिप्सिस (…) से काटा जाता है — और एडिटर कभी बगल में स्क्रॉल नहीं होता, उन विंडो तक में भी जो किसी होस्ट को देनी चाहिए उससे संकरी हों (150 % डिस्प्ले स्केलिंग वाले एक होस्ट ने इसे 930 पिक्सेल दिए)। मैप का रूलर अपनी संख्याओं को उनकी मापी गई चौड़ाई के हिसाब से फैलाता है, छोटे मैप पर लेन और सिकुड़ जाती हैं ताकि पूरा सेशन फिर भी दिखे, और लेन के नामों को उतनी जगह मिलती है जितनी उन्हें चाहिए।","changelog.6d85908ca753":"<strong>नाम, सिर्फ़ एक बार।</strong> हर फ़ॉर्मैट ठीक “Freally Unloop” बताता है, और उसके साथ कुछ भी इसे दोहराता नहीं, इसलिए होस्ट का टाइटल बार इसे कभी दो बार नहीं दिखाता।","changelog.696a4fb40d61":"<strong>होस्ट उस Unloop को बंद करते समय क्रैश हो सकता था जिसे उसने अभी-अभी खोला था</strong> — एक तेज़ प्लगइन स्कैन, एक वैलिडेटर, लोड होते-होते बंद किया गया प्रोजेक्ट। प्लगइन फ़्रेमवर्क का बैकग्राउंड वर्कर, जिसे हर इंस्टेंस साझा करता है, किसी पहले ही जा चुके इंस्टेंस का छोड़ा काम मिलने पर हमेशा के लिए रुक जाता था, और अगला बंद होने वाला इंस्टेंस होस्ट को गिरा देता था। Unloop अब उसे कोई काम नहीं देता: हर इंस्टेंस अपना काम अपने ही थ्रेड पर करता है।","changelog.107aa869557c":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-09-26\">2026-09-26</time></span><span class=\"release__title\">M: जादुई पल</span>","changelog.edddef519a58":"लूप होती बीट पर एक Unloop अब पूरा ट्रैक लाइव बजाता है: कोई कलाकार, प्रोड्यूसर या शैली चुनें, “जनरेट करें” दबाएँ, अपने DAW में प्ले दबाएँ, और आपका लूप होस्ट के साथ ताल में एक अरेंज किया हुआ गाना बन जाता है — पार्ट हटते और लौटते हुए, फ़िल्टर स्वीप, स्टटर बिल्ड, टेप स्टॉप — बिना क्लिक और बिना अतिरिक्त लेटेंसी के, और मैप व कंसोल उसके साथ चलते हैं।","changelog.c542a3d7af1e":"<strong>लाइव परफ़ॉर्मेंस (वन-लूप मोड)।</strong> एक इंस्टेंस आपके लूप को तीन बैंड्स में बाँटता है — लो (120 Hz से नीचे), मिड और हाई (4 kHz से ऊपर), एक Linkwitz–Riley विभाजन जो जुड़कर फिर से सपाट हो जाता है — और उन पर प्लान बजाता है: हर बैंड वहीं आता-जाता है जहाँ ट्रैक कहता है, और पूरे लूप के लिए लिखे मूव्स पूरे लूप पर काम करते हैं। आपकी लूप फ़ाइल में कुछ भी नहीं बदलता।","changelog.f209a2fc6b77":"<strong>पहले मूव्स जिन्हें आप सुन सकते हैं</strong>: म्यूट, अनम्यूट, ड्रॉप-आउट और कट; फ़िल्टर स्वीप (लो- या हाई-पास, हर टिक पर कटऑफ़ सटीक, प्लान के वक्र से मुड़ा हुआ); स्टटर बिल्ड (पिछली बीट, और तेज़ी से बार-बार ट्रिगर होती, ऊपर चढ़ती हुई); और टेप स्टॉप (लूप सीमा पर धीमा होते-होते रुक जाता है)। हर किनारा एक नरम रैंप है (5 ms), जिसे संगीत से −60 dB नीचे के क्लिक टेस्ट पर परखा जाता है। बाकी शब्दावली मैप पर है, उस संस्करण के साथ चिह्नित जिसमें वह आएगी।","changelog.079fb6a04db0":"<strong>होस्ट के साथ ताल में, वह चाहे जैसे बजे।</strong> सॉन्ग घड़ी ट्रैक को आपकी टाइमलाइन पर आपके चुने बार से बिछाती है; लूप घड़ी घूमते लूप को गिनती है — FL Studio का पैटर्न मोड, लूप ब्रेस, Ableton का सेशन व्यू — इसलिए 200 लूप ठीक 200 लूप होते हैं। <em>स्वतः</em> हर बार चलाने पर एक घड़ी चुनता है और घड़ी के बैज पर कारण बताता है। टेम्पो बदलने पर हर मूव अपने बार पर बना रहता है।","changelog.dd9565bb9638":"<strong>टेम्पो होस्ट का है।</strong> टेम्पो चिप DAW का BPM दिखाती है और यह कि वह आपके चुने नाम के अनुकूल है या नहीं — हाफ़ और डबल टाइम गिने जाते हैं, अनुपात बताया जाता है — और जब अनुकूल न हो, तो आम टेम्पो और सीमा के भीतर का सबसे नज़दीकी टेम्पो, जिसे आप कॉपी करके ख़ुद सेट कर सकें। Unloop आपके DAW का टेम्पो कभी नहीं बदलता।","changelog.43c245c305f5":"सभी 2,413 नामों पर <strong>खोज</strong>, जो Freally MIDI Master की खोज की तरह टाइपो को माफ़ करती है (“metro bumin” लिखने पर Metro Boomin मिलता है), हर पंक्ति बताती है कि वह क्या है और उसका कितना हिस्सा उसका अपना है; हाल के चुनाव सबसे पहले; कुछ मेल न खाए तो “क्या आपका मतलब था”। कुछ भी दबाने से पहले <strong>मॉडल कार्ड</strong>, ख़ाली मैप पर किसी मोड के ढाँचे के प्रीव्यू के साथ। <strong>मोड पिकर</strong> (<em>कोई भी</em> के साथ) और <strong>सीड चिप</strong> — इसे कॉपी करें, या वही ट्रैक फिर से पाने के लिए कोई सीड पेस्ट करें।","changelog.c4d42bdbfb75":"<strong>अरेंजमेंट मैप</strong>: सेक्शन, तीन बैंड लेन जिनमें हर क्लिप के फ़ेड वैसे ही बने हैं जैसे ऑडियो उन्हें आकार देता है, हर मूव के लिए एक चिह्न, ऊर्जा वक्र, मिनट और सेकंड वाला बार रूलर, और होस्ट का प्लेहेड; बजते समय मूव अपनी लेन पर चमक उठता है। नया ट्रैक आने पर मैप धीरे-धीरे उभरता है (कोई कुंजी या क्लिक इसे छोड़ देता है; कम मोशन की सेटिंग में तुरंत)।","changelog.b9acf1dcbf7e":"<strong>कंसोल</strong>: एक चैनल स्ट्रिप जिसके लैंप, फ़ेडर और फ़िल्टर नॉब वही दिखाते हैं जो ऑडियो थ्रेड ने असल में लागू किया, असली बैलिस्टिक्स वाला VU मीटर, और मास्टर सेक्शन — “जनरेट करें”, “फिर से बनाएँ”, टेप काउंटर और सीड। जब कुछ भी Unloop को यह नहीं बताता कि आपका लूप कितना लंबा है, तो यह एक बार पूछता है (2, 4, 8 या 16 बार) और “जनरेट करें” को कभी नहीं रोकता।","changelog.7e08eeb2a0b2":"<strong>प्रोजेक्ट याद रखते हैं।</strong> नाम, मोड, सीड, लूप की लंबाई और सेशन आपके DAW प्रोजेक्ट में सेव होते हैं; उसे फिर से खोलने पर वही ट्रैक दोबारा बनता है — वही प्लान, हैश तक — और अगर लूप की लंबाई या टाइम सिग्नेचर बदलता है (आपका जवाब, आपके DAW का लूप ब्रेस), तो उसके लिए प्लान फिर से बनता है।","changelog.cac34fa81c8b":"<strong>हर मॉडल, शैली और मोड का नाम साथ आए Noto फ़ॉन्ट से जाँचा जाता है</strong>, जैसे अनुवाद पहले से जाँचे जाते थे, इसलिए रोस्टर में दिखने वाला कोई भी नाम सिस्टम फ़ॉन्ट या ग़ायब-ग्लिफ़ वाले बॉक्स पर नहीं गिर सकता।","changelog.7962b5beebac":"<strong>Bypass</strong> परफ़ॉर्मेंस <em>और</em> Output ट्रिम दोनों को एक साथ धीरे-धीरे हटाता है, फिर आपका ऑडियो बिना छुए आगे जाने देता है; मीटर ट्रिम के बाद वही पढ़ते हैं जो असल में प्लगइन से बाहर निकलता है।","changelog.ec1231a741d1":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-09-24\">2026-09-24</time></span><span class=\"release__title\">P: प्लानर</span>","changelog.475985e8de84":"2,413 नामों में से कोई भी अब एक नियतात्मक अरेंजमेंट प्लान बन जाता है। अभी इसे कुछ नहीं बजाता — पहली लाइव परफ़ॉर्मेंस <code>v0.3.0</code> में है — लेकिन ट्रैक के लिए ज़रूरी हर फ़ैसला यहीं, ग्रिड पर, एक भी सैंपल बजने से पहले लिया जाता है।","changelog.79a17b028e4f":"<strong>प्लानर।</strong> एक नाम, एक मोड, सेशन और एक सीड मिलकर पूरा ट्रैक बनते हैं: गाने का ढाँचा, 4/8/16-बार फ़्रेज़ ग्रिड पर हर सेक्शन की लंबाई, हर सेक्शन में कौन-से पार्ट बजते हैं और कैसे (सिर्फ़ हैट्स, फ़िल्टर किए हुए, फ़ेड किए हुए, हाफ़ टाइम), हर मूव टिक तक सटीक जगह पर — ड्रॉप-आउट, कट, स्टटर बिल्ड, रोल, स्वीप, टेप स्टॉप, बीट स्विच, ट्रांज़िशन FX, ईयर कैंडी, प्रोड्यूसर टैग — और बार-दर-बार ऊर्जा वक्र। एक जैसे इनपुट बाइट-दर-बाइट एक जैसा प्लान देते हैं, जिस पर BLAKE3 प्लान हैश की मुहर लगती है। यह तीन मिनट के ट्रैक की योजना एक मिलीसेकंड से कम में बना लेता है।","changelog.989666ca013f":"<strong>हर शैली एक से ज़्यादा तरीक़ों से अरेंज होती है।</strong> मोड — रेडियो कट, मिक्सटेप कट, क्लब/DJ कट, स्विच-अप, न्यूनतम, सादा, विस्तारित, और शैली के अपने खास मोड (boom bap के लिए क्लासिक, पोज़ कट और बीट टेप; 2000s R&amp;B के लिए स्लो जैम और इंटरल्यूड; liquid drum &amp; bass के लिए वोकल कट)। <em>कोई भी</em> अपने वज़न के हिसाब से एक मोड चुनता है।","changelog.5de91eed2226":"<strong>पहले 12 शैली मॉडल</strong>, अरेंजमेंट शोध के आधार पर लिखे गए: trap, dark trap, plugg, pluggnb, rage, UK drill, NY drill, boom bap, 2000s R&amp;B, 2020s pop, country-pop और liquid drum &amp; bass — 39 मोड — और साथ में वह डिफ़ॉल्ट जिस पर बाकी हर नाम टिका है।","changelog.a883b8d3cf75":"<strong>पूरा रोस्टर, आयात किया गया।</strong> 2,413 नाम — 1,507 कलाकार, 833 प्रोड्यूसर, 73 शैलियाँ — Freally MIDI Master के डेटासेट से, पिन की गई रिलीज़ पर, उनके उपनामों, दौर, शैलियों, विरासत, टेम्पो और गानों के ढाँचों के साथ। आयात बाइट तक दोहराया जा सकता है, और जो भी फ़ील्ड यह नहीं पढ़ता, उसका कारण शब्दों में लिखा है।","changelog.8f2f1aef5133":"<strong>हर नाम पर एक ईमानदार बैज।</strong> <em>प्रमुख</em> (उसका अपना मॉडल), <em>मानक</em> (अपने गानों के ढाँचे या सेक्शन की लंबाई बजाता है — 1,157 नाम) या <em>विरासत में</em> (उसकी शैली का — 1,244 नाम), जो इस पर आधारित है कि प्लानर ने असल में क्या इस्तेमाल किया।","changelog.33b91bcddab0":"<strong>सिर्फ़ एक चीज़ फिर से बनाएँ।</strong> प्लान सिर्फ़ अपनी ईयर कैंडी, या एक सेक्शन के पार्ट दोबारा बना सकता है, और बाकी सब ठीक वैसा ही रहता है जैसा था।","changelog.fc97f471bb4b":"<strong>वन-लूप की तैयारी।</strong> हर मूव बताता है कि एक लूप को तीन बैंड्स में बाँटने वाला अकेला इंस्टेंस उसके साथ क्या करेगा, और जब किसी बैंड को ऐसे पार्ट की जगह लेनी पड़े जिसे वह अलग नहीं कर सकता, तो प्लान यह बताता है।","changelog.cba5495f6089":"<strong>मॉडल कार्ड</strong>: मोड, ढाँचे, सेक्शन की लंबाई, खास मूव्स, आम ऊर्जा, टेम्पो, विरासत और स्रोत — जो प्लानर बजाता है उसी से गणना किए गए, अस्वीकरण के साथ।","changelog.88d2b1cd382c":"<strong><code>unloopc</code>, डेटासेट कंपाइलर</strong> — <code>validate</code>, <code>stats</code>, <code>coverage</code>, <code>distinct</code>, <code>card</code>, <code>plan</code>, <code>import-roster</code>, <code>schema</code> — और <code>npm run dataset:*</code>। मॉडल स्कीमा और शब्दावली फ़ाइल Rust टाइप्स से जनरेट होती हैं।","changelog.b582568bbaf2":"<strong>गेट्स</strong>: रोस्टर आयात, स्कीमा और हर मॉडल (<code>ci:local</code> और <code>ci:linux</code>); प्लानर द्वारा पढ़ी जाने वाली हर लिखी गई कुंजी — हर एक के लिए साबित किया गया कि उसके बदलने पर प्लान बदलता है; हर लिखी गई स्ट्रिंग उसकी शब्दावली से पार्स की गई; हर शैली के लिए दो या ज़्यादा अलग मोड; 24 गोल्डन प्लान; पूरे रोस्टर का दो बार प्लान बनाकर तुलना; 95वें पर्सेंटाइल पर 50 ms का प्लानिंग बजट; और प्लगइन की हर <code>unsafe</code> जगह दस्तावेज़ में दर्ज सूची तक सीमित। हर गेट पर भरोसा करने से पहले उसे फ़ेल होते देखा गया।","changelog.c83336253c11":"<strong>“जनरेट करें” के नीचे का नोट</strong> अब कहता है कि यह अगले बिल्ड में आएगा — जिस प्लानर का इसे इंतज़ार था वह आ गया है, और बटन <code>v0.3.0</code> में जोड़ा जाएगा — सभी 18 भाषाओं में।","changelog.5a7a1b20ab13":"<strong>स्केल किए गए डिस्प्ले पर स्टैंडअलोन (Windows)।</strong> पेज विंडो के अंदर खिसका हुआ बैठता था, दाईं और नीचे से कटा हुआ, और विंडो खींचते समय फ़्रेम के पीछे सरक जाता था: प्रोसेस DPI से अनजान था, इसलिए Windows विंडो को खींचकर बड़ा करता था जबकि वेब व्यू असली पिक्सेल पर बनाता था। स्टैंडअलोन अब किसी भी विंडो के बनने से पहले प्रति-मॉनिटर DPI जागरूकता घोषित करता है।","changelog.df00e0d65bc5":"<strong>स्टैंडअलोन प्लगइन के आकार में खुलता है।</strong> यह डिस्प्ले का स्केल nih-plug को <code>--dpi-scale</code> के रूप में देता है (स्पष्ट रूप से दिया गया <code>--dpi-scale</code> अब भी प्राथमिकता पाता है), इसलिए यह उतना ही बड़ा खुलता है जितना वही एडिटर किसी होस्ट में।","changelog.0e3c3179efba":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-09-24\">2026-09-24</time></span><span class=\"release__title\">F: नींव</span>","changelog.42f5ee22d43e":"वह ख़ाली प्रोडक्ट जिस पर बाद का हर पायदान बनता है: यह लोड होता है, ऑडियो को बिना छुए आगे जाने देता है, अपना एडिटर खोलता है, और हर क्वालिटी गेट चलता है।","changelog.c794a76c2618":"<strong>प्लगइन, एक ही बाइनरी से हर फ़ॉर्मैट में।</strong> एक nih-plug CLAP प्लगइन, जिसके VST3 और AUv2 एंट्री पॉइंट <code>clap-wrapper</code> से बनाए जाते हैं (लाइसेंस के लिहाज़ से साफ़: कोई GPL VST3 बाइंडिंग नहीं), और साथ में स्टैंडअलोन ऐप्लिकेशन। स्टीरियो या मोनो, पास-थ्रू, ज़ीरो लेटेंसी, संस्करण वाली सेव की गई स्टेट जो होस्ट को क्रैश करने के बजाय हर उस चीज़ को अस्वीकार करती है जिसे वह पढ़ नहीं सकती, होस्ट का <strong>Bypass</strong> स्विच और एक <strong>Output</strong> ट्रिम (−24 से +6 dB, स्मूद किया हुआ)।","changelog.6f91cc8aeb3f":"<strong>एडिटर का ढाँचा।</strong> साझा Freally वेबव्यू अडैप्टर में React एडिटर, जो एक सख़्त Content Security Policy के तहत बाइनरी के अंदर से परोसा जाता है, प्लगइन तक एक टाइप्ड ब्रिज के साथ (रिक्वेस्ट/रिस्पॉन्स और पोल किए गए इवेंट), जिसके TypeScript टाइप Rust टाइप्स से जनरेट होते हैं।","changelog.e6f8feb48be4":"<strong>Freally टाइटल बार।</strong> प्रोडक्ट का नाम 3D में, अपनी Y धुरी पर पीछे की ओर घूमता, ठहरता, और फिर से घूमकर लौटता — Freally MIDI Master और Freally Oscillate की तरह, थोड़ा बड़ा ताकि घूमना आसानी से दिखे; कम मोशन की सेटिंग में स्थिर।","changelog.f556ccffa36f":"<strong>लाइसेंस अनुबंध</strong> (<code>EULA.md</code>) और उसका गेट: Unloop पहली बार खुलने पर आपसे इसे स्वीकार करने को कहता है और जब तक आप स्वीकार न करें, निष्क्रिय रहता है। निष्क्रिय प्लगइन आपका ऑडियो बिना छुए आगे जाने देता है — आपकी सहमति से पहले होस्ट या सेव किया गया प्रोजेक्ट जो भी सेट करे, Output ट्रिम समेत, कुछ भी उसे नहीं बदलता। एक इंस्टेंस में स्वीकार या अस्वीकार करना तुरंत हर खुले इंस्टेंस तक पहुँचता है, और जो अस्वीकृति सेव नहीं हो सकी, वह यह बताती है, बजाय इसके कि अगला सेशन ऐसे खुले मानो आपने सहमति दी हो।","changelog.b3fe519bf775":"<strong><code>THIRD-PARTY-NOTICES.md</code></strong>, जो असल में शिप होने वाली चीज़ों से जनरेट होता है — हर OS पर प्लगइन और स्टैंडअलोन का हर क्रेट, एडिटर के पैकेज और फ़ॉन्ट, उनके लाइसेंस और कॉपीराइट धारकों के साथ — और फ़ॉन्ट के लाइसेंस (<code>OFL-Noto.txt</code>) के साथ हर रिलीज़ आर्काइव में शामिल रहता है।","changelog.565020242597":"<strong>डिज़ाइन टोकन और थीम</strong> — गहरी, हल्की और सिस्टम — दोनों में WCAG 2.1 AA कंट्रास्ट की जाँच के साथ; सभी 18 भाषाओं के लिए Noto फ़ॉन्ट साथ शामिल।","changelog.7ddbeff39e12":"एडिटर में <strong>18 भाषाएँ</strong>, एक गेट के साथ जो हर कैटलॉग को एक-दूसरे से मेल में रखता है।","changelog.6ad657e4e2ad":"<strong>डायग्नोस्टिक ट्रेसिंग</strong> (<code>UNLOOP_TRACE=all</code>, एक लॉग फ़ाइल में लिखी जाती है) उन समस्याओं के लिए जो सिर्फ़ होस्ट के अंदर होती हैं।","changelog.594511701ab8":"Windows, macOS, Linux और डॉक्स साइट के लिए एक ही मास्टर आइकन से बनाए गए <strong>आइकन</strong>।","changelog.3ad9c9b08c97":"<strong>क्वालिटी गेट्स</strong>, <code>npm run ci:local</code> (Windows) और <code>npm run ci:linux</code> (Docker Desktop) में: फ़ॉर्मैटिंग, लिंट, टाइप जाँच, <code>std::net</code> पर प्रतिबंध के साथ clippy, यूनिट और Playwright टेस्ट, ऑडियो थ्रेड में मेमोरी आवंटन गिनने वाला टेस्ट, बिना-AI/बिना-नेटवर्क/बिना-टेलीमेट्री डिपेंडेंसी गेट, लाइसेंस और एडवाइज़री नीति, जनरेट किए गए नोटिस का गेट, साझा कोड और बाइंडिंग-ड्रिफ़्ट गेट्स, डॉक्स साइट के लिए 1.0 से पहले कोई डाउनलोड नहीं वाला गेट, और clap-validator व pluginval (strictness 10)। हर गेट पर भरोसा करने से पहले उसे फ़ेल होते देखा गया।","changelog.29509f5c50ce":"<strong>रिलीज़ टूलिंग</strong>: <code>npm run release:bundle</code> और सिर्फ़ टैग पर चलने वाला रिलीज़ वर्कफ़्लो, जो थर्ड-पार्टी बिल्ड कोड चलाते समय न कोई राइट टोकन रखता है न प्राइवेट-रिपॉज़िटरी टोकन, और प्रकाशित करने से पहले जाँचता है कि हर आर्काइव सच में zip या gzip है।","changelog.361aee95901b":"सार्वजनिक संस्करण सीढ़ी के साथ डॉक्स साइट का ढाँचा।","changelog.388399ae707a":"एडिटर का ब्रिज सिर्फ़ एडिटर के अपने JSON <code>POST</code> का जवाब देता है: जो पेज Unloop का नहीं है — विंडो पर छोड़ा गया कोई लिंक या फ़ाइल — वह न उसे कॉल कर सकता है न उसके जवाब पढ़ सकता है, और कुछ छोड़ने पर अब एडिटर कहीं नेविगेट नहीं होता।","changelog.1f976b647d80":"रिलीज़ प्लगइन कोई DevTools डिबगिंग पोर्ट नहीं खोलता (Freally MIDI Master का टेस्ट हुक, जो अब एक ऐसे फ़ीचर के पीछे है जिसके बिना Unloop बिल्ड होता है), और बंडल जाँच ऐसी बाइनरी को अस्वीकार करती है जो पोर्ट खोल सकती हो, या जो पिन किए गए सोर्स से न बनी हो।","changelog.f65776baedfa":"डायग्नोस्टिक ट्रेस अब अपना कंसोल न रहने पर होस्ट को नहीं गिरा सकता।","changelog.2fedafc14be7":"<strong>Linux: एडिटर प्लगइन से बात नहीं कर पाता था।</strong> वेबव्यू हर ब्रिज रिक्वेस्ट को ख़ाली बॉडी के साथ पहुँचाता था, इसलिए लाइसेंस अनुबंध कभी स्वीकार नहीं हो पाता था। अब रिक्वेस्ट बॉडी पहुँचती है (WebKitGTK 2.40 या बाद का)।","changelog.55bda2d0ead3":"<code>-p &lt;period&gt;</code> दिए जाने पर स्टैंडअलोन अब शुरू होने से इनकार नहीं करता।","changelog.bf6b0c2f06b4":"<strong>Linux: प्लगइन को लोड और अनलोड करके स्कैन करने वाला होस्ट अब कुछ सेकंड बाद क्रैश नहीं होता।</strong> एडिटर का WebKitGTK अपने साथ JavaScriptCore थ्रेड लाता है; प्लगइन लाइब्रेरी अब होस्ट के बंद होने तक लोड रहती है (clap-validator के स्कैन टेस्ट ने यह पकड़ा)।","changelog.f95b9de4af46":"<strong>Linux: एडिटर जल्दी बंद करने से अब होस्ट बंद नहीं होता</strong> — साझा Freally वेबव्यू अडैप्टर में दो सुधार (उसके GTK थ्रेड पर एक X एरर ट्रैप, और ऐसा बंद होना जो वेब व्यू के हट जाने का इंतज़ार करता है)। strictness 10 पर pluginval अब Linux पर पास होता है, एडिटर टेस्ट समेत।","changelog.51862fa2d198":"अपस्ट्रीम में ठीक किया गया (साझा nih-plug फ़ोर्क में, जिसे Freally MIDI Master के <code>shared-v1</code> के ज़रिए इस्तेमाल किया जाता है)","changelog.89bea0569ab2":"प्रोजेक्ट लोड होने के बाद अब CLAP होस्ट को बताया जाता है कि उसके पैरामीटर मान बदल गए हैं (clap-validator <code>state-reproducibility-*</code>)।","changelog.26edfb636bce":"एडिटर खोलना या बंद करना अब ऐसा लॉक नहीं पकड़ता जिसमें एडिटर का अपना स्टार्ट-अप दोबारा घुस सकता था — होस्ट के मुख्य थ्रेड का डेडलॉक (pluginval <code>Editor Automation</code>)।","changelog.e6463781d61f":"<code>rtrb</code> को 0.3.5 पर ले जाया गया, जिससे RUSTSEC-2026-0274 (एक use-after-free) को अनदेखा करने के बजाय उसके स्रोत पर ही बंद किया गया।","changelog.d9577706c4ec":"होस्ट: FL Studio, Ableton Live और Reaper में लोड होना हाथ से साबित किया जाता है, CI से नहीं, और होस्ट मैट्रिक्स की वे पंक्तियाँ इस पायदान पर अभी पूरी की जानी बाकी हैं; वैलिडेटर साबित करते हैं कि प्लगइन सही ढंग से बना है, और स्टैंडअलोन चलाया जा चुका है।","changelog.edf3e5f9658b":"AU बनाया और बंडल किया गया है पर अभी साबित नहीं हुआ: किसी Mac ने इसे अब तक लोड नहीं किया। Linux एडिटर एक कंटेनर में बनाया और वैलिडेट किया गया है पर अभी किसी असली Linux सेशन में इस्तेमाल नहीं हुआ।","changelog.c95891622d38":"साझा वेबव्यू अडैप्टर अपना ब्राउज़र डेटा Freally MIDI Master के नाम वाले फ़ोल्डर में रखता है, जब तक अडैप्टर अपने फ़ोल्डर का नाम ख़ुद रखना न सीख ले (रोडमैप)।"};
